-- ========== cash_procs.sql ==========
DELIMITER $$
DROP FUNCTION if EXISTS sf_create_cashdoc$$
CREATE FUNCTION sf_create_cashdoc(params JSON)
RETURNS JSON
BEGIN
-- 2025-10-12 13:41:38
DECLARE cashdoc CHAR(36) COLLATE LATIN1_GENERAL_CI;
SET cashdoc = JSON_VALUE(params, '$.f_id');
if (cashdoc IS NULL) then
	SELECT UUID() INTO cashdoc;
ELSE 
	SELECT sf_remove_cashdoc(cashdoc) INTO @tmp;
END if;
INSERT INTO a_header (f_id, f_type, f_state, f_date, f_operator, f_currency, f_comment, f_amount) 
VALUES (cashdoc, 5, 1, JSON_VALUE(params, '$.f_date'), JSON_VALUE(params, '$.f_operator'), JSON_VALUE(params, '$.f_currency'), JSON_VALUE(params, '$.f_comment'), JSON_VALUE(params, '$.f_amount'));
INSERT INTO a_header_cash (f_id, f_cashin, f_cashout) VALUES (cashdoc, JSON_VALUE(params, '$.f_cashin'), JSON_VALUE(params, '$.f_cashout'));
if (coalesce(JSON_VALUE(params, '$.f_cashin'), 0)>0) then
	INSERT INTO e_cash (f_id, f_header, f_cash, f_sign, f_remarks, f_amount, f_row) VALUES (UUID(), cashdoc, JSON_VALUE(params, '$.f_cashin'), 1, JSON_VALUE(params, '$.f_purpose'), JSON_VALUE(params, '$.f_amount'), 0);
END if;
if (COALESCE(JSON_VALUE(params, '$.f_cashout'), 0)>0) then
	INSERT INTO e_cash (f_id, f_header, f_cash, f_sign, f_remarks, f_amount, f_row) VALUES (UUID(), cashdoc, JSON_VALUE(params, '$.f_cashout'), -1, JSON_VALUE(params, '$.f_purpose'), JSON_VALUE(params, '$.f_amount'), 0);
END if;
RETURN JSON_OBJECT('status', 1, 'cashdoc', cashdoc);
END$$

DROP FUNCTION if EXISTS sf_remove_cashdoc$$
CREATE FUNCTION sf_remove_cashdoc(cashdoc CHAR(36) COLLATE LATIN1_GENERAL_CI)
RETURNS JSON
BEGIN
-- 2025-10-12 13:41:44
	delete from e_cash where f_header=cashdoc;
	delete from a_header_cash where f_id=cashdoc;
	delete from a_header where f_id=cashdoc;
	RETURN JSON_OBJECT('status', 1);
END$$
DELIMITER ;
DELIMITER ;

-- ========== create_shop_order.sql ==========
DROP PROCEDURE IF EXISTS sf_create_shop_order;
DELIMITER $$
CREATE PROCEDURE sf_create_shop_order(params JSON)
sp:
BEGIN

    DECLARE jfiscal json;
    DECLARE jdata json DEFAULT '{}';

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            RESIGNAL;
        END;


#27/02/2026 12:48
    SELECT CURRENT_TIMESTAMP() INTO @t1;
    SELECT JSON_EXTRACT(params, '$.header') INTO @jh;
    SELECT JSON_EXTRACT(params, '$.draft') INTO @jd;
    SELECT JSON_EXTRACT(params, '$.goods') INTO @jg;
    SELECT JSON_EXTRACT(params, '$.history') INTO @jhistory;
    SELECT JSON_EXTRACT(params, '$.accumulate') INTO @jaccumulate;
    SELECT JSON_EXTRACT(params, '$.flags') INTO @flags;
    SELECT JSON_OBJECT('status', CAST(1 AS INT), 'message', '') INTO @result;
    SELECT JSON_EXTRACT(params, '$.fiscal') INTO jfiscal;
    SELECT sv.f_value
    INTO @cashid
    FROM s_settings_values sv
    WHERE sv.f_key = 32
      AND f_settings = (SELECT f_settings FROM h_halls WHERE f_id = JSON_VALUE(@jh, '$.f_hall') LIMIT 1);
    SELECT sv.f_value
    INTO @nocashid
    FROM s_settings_values sv
    WHERE sv.f_key = 35
      AND f_settings = (SELECT f_settings FROM h_halls WHERE f_id = JSON_VALUE(@jh, '$.f_hall') LIMIT 1);

    START TRANSACTION;

#clear previuosly saved data
    SELECT f_id INTO @tid FROM o_header WHERE f_id = JSON_VALUE(@jh, '$.f_id');
    IF (@tid IS NOT NULL) THEN
        SELECT f_id INTO @t FROM a_header_cash WHERE f_oheader = JSON_VALUE(@jh, '$.f_id');
        DELETE FROM b_clients_debts WHERE f_order = JSON_VALUE(@jh, '$.f_id');
        DELETE FROM e_cash WHERE f_header = @t;
        DELETE FROM a_header_cash WHERE f_id = @t;
        DELETE FROM a_header WHERE f_id = @t;
        DELETE FROM o_goods WHERE f_header = JSON_VALUE(@jh, '$.f_id');
        DELETE FROM b_history WHERE f_id = JSON_VALUE(@jh, '$.f_id');
        DELETE FROM o_header WHERE f_id = JSON_VALUE(@jh, '$.f_id');
        DELETE FROM o_header_flags WHERE f_id = JSON_VALUE(@jh, '$.f_id');
    END IF;
#delete from o_draft_sale_body where f_header=@tid;
    DELETE FROM o_draft_sale WHERE f_id = JSON_VALUE(@jh, '$.f_id');

#hall id
    IF JSON_VALUE(@jh, '$.f_hallid') = 0 OR JSON_VALUE(@jh, '$.f_hallid') IS NULL THEN
        SELECT f_counter + 1, f_prefix
        INTO @counter, @prefix
        FROM h_halls
        WHERE f_id = JSON_VALUE(@jh, '$.f_hall') FOR
        UPDATE;
        UPDATE h_halls SET f_counter=@counter WHERE f_id = JSON_VALUE(@jh, '$.f_hall');
        SET @jh = JSON_SET(@jh, '$.f_hallid', @counter);
        SET @jh = JSON_SET(@jh, '$.f_prefix', @prefix);
        SET @result = JSON_SET(@result, '$.f_hallid', @counter);
        SET @result = JSON_SET(@result, '$.f_prefix', @prefix);
    END IF;


#o_header
    SET jdata = JSON_SET(jdata, '$.f_fiscal', COALESCE(JSON_COMPACT(jfiscal), JSON_OBJECT()));
    INSERT INTO `o_header` (`f_id`, `f_hallid`, `f_prefix`, `f_state`, `f_hall`,
                            `f_table`, `f_dateOpen`, `f_dateClose`, `f_dateCash`, `f_timeOpen`,
                            `f_timeClose`, `f_cashier`, `f_staff`, `f_comment`, `f_print`,
                            `f_amountTotal`, `f_amountCash`, `f_amountCard`, `f_amountprepaid`, `f_amountBank`,
                            `f_amountcredit`, `f_amountIdram`, `f_amountTelcell`, `f_amountDebt`, `f_amountPayX`,
                            `f_amountOther`, `f_amountService`, `f_amountDiscount`,
                            `f_serviceFactor`, `f_discountFactor`, `f_creditCardId`, `f_otherId`, `f_shift`,
                            `f_source`, `f_saletype`, `f_partner`, `f_currentstaff`, `f_guests`, `f_precheck`,
                            `f_cash`, `f_change`, `f_hotel`, `f_currency`, `f_taxpayertin`, `f_data`)
    VALUES (JSON_VALUE(@jh, '$.f_id'), @counter, @prefix, JSON_VALUE(@jh, '$.f_state'), JSON_VALUE(@jh, '$.f_hall'),
            JSON_VALUE(@jh, '$.f_table'), JSON_VALUE(@jh, '$.f_dateopen'), JSON_VALUE(@jh, '$.f_dateclose'),
            JSON_VALUE(@jh, '$.f_datecash'), JSON_VALUE(@jh, '$.f_timeopen'),
            JSON_VALUE(@jh, '$.f_timeclose'), JSON_VALUE(@jh, '$.f_cashier'), JSON_VALUE(@jh, '$.f_staff'),
            JSON_VALUE(@jh, '$.f_comment'), JSON_VALUE(@jh, '$.f_print'),
            JSON_VALUE(@jh, '$.f_amounttotal'), JSON_VALUE(@jh, '$.f_amountcash'), JSON_VALUE(@jh, '$.f_amountcard'),
            JSON_VALUE(@jh, '$.f_amountprepaid'), JSON_VALUE(@jh, '$.f_amountbank'),
            JSON_VALUE(@jh, '$.f_amountcredit'), JSON_VALUE(@jh, '$.f_amountidram'),
            JSON_VALUE(@jh, '$.f_amounttelcell'), JSON_VALUE(@jh, '$.f_amountdebt'), JSON_VALUE(@jh, '$.f_amountpayx'),
            JSON_VALUE(@jh, '$.f_amountother'), JSON_VALUE(@jh, '$.f_amountservice'),
            JSON_VALUE(@jh, '$.f_amountdiscount'),
            JSON_VALUE(@jh, '$.f_servicefactor'), JSON_VALUE(@jh, '$.f_discountfactor'),
            JSON_VALUE(@jh, '$.f_creditcardid'), JSON_VALUE(@jh, '$.f_otherid'), JSON_VALUE(@jh, '$.f_shift'),
            JSON_VALUE(@jh, '$.f_source'), JSON_VALUE(@jh, '$.f_saletype'), JSON_VALUE(@jh, '$.f_partner'),
            JSON_VALUE(@jh, '$.f_currentstaff'), JSON_VALUE(@jh, '$.f_guests'), JSON_VALUE(@jh, '$.f_precheck'),
            JSON_VALUE(@jh, '$.f_cash'), JSON_VALUE(@jh, '$.f_change'), JSON_VALUE(@jh, '$.f_hotel'),
            JSON_VALUE(@jh, '$.f_currency'), JSON_VALUE(@jh, '$.f_taxpayertin'),
            jdata);


#o_header_flags
    INSERT INTO o_header_flags(f_id, f_1, f_2, f_3, f_4, f_5)
    VALUES (JSON_VALUE(@jh, '$.f_id'),
            JSON_VALUE(@flags, '$.f_1'), JSON_VALUE(@flags, '$.f_2'), JSON_VALUE(@flags, '$.f_3'),
            JSON_VALUE(@flags, '$.f_4'), JSON_VALUE(@flags, '$.f_5'));


    INSERT INTO a_result(f_request, f_result) VALUES ('tuta7', JSON_VALUE(@jh, '$.f_id'));
#o_draft_sale
    INSERT INTO o_draft_sale (f_id, f_state, f_date, f_datefor)
    VALUES (JSON_VALUE(@jh, '$.f_id'), JSON_VALUE(@jh, '$.f_state'), JSON_VALUE(@jh, '$.f_datecash'),
            JSON_VALUE(@jd, 'f_delivery'));

#b_history
    IF (JSON_VALUE(@jhistory, '$.f_type') > 0) THEN
        #kostil
        DELETE FROM b_history WHERE f_id = JSON_VALUE(@jh, '$.f_id');
        INSERT INTO b_history (f_id, f_type, f_card, f_value, f_data)
        VALUES (JSON_VALUE(@jh, '$.f_id'), JSON_VALUE(@jhistory, '$.f_type'), JSON_VALUE(@jhistory, '$.f_card'),
                JSON_VALUE(@jhistory, '$.f_value'), JSON_VALUE(@jhistory, '$.f_data'));
    END IF;


#accumulate card
    IF (@jaccumulate IS NOT NULL) THEN
        IF (JSON_VALUE(@jaccumulate, '$.accumulatespend') > 0) THEN
            INSERT INTO b_gift_card_history (f_card, f_trsale, f_amount)
            VALUES (JSON_VALUE(@jaccumulate, '$.card'), JSON_VALUE(@jh, '$.f_id'),
                    COALESCE(JSON_VALUE(@jaccumulate, '$.accumulatespend'), 0) * -1);
        ELSE
            INSERT INTO b_gift_card_history (f_card, f_trsale, f_amount)
            VALUES (JSON_VALUE(@jaccumulate, '$.card'), JSON_VALUE(@jh, '$.f_id'),
                    COALESCE(JSON_VALUE(@jaccumulate, '$.accumulate'), 0));
        END IF;
    END IF;


#goods
    SET @i = 0;
    SET @needstore = 0;
    WHILE (@i < JSON_LENGTH(@jg))
        DO
            SELECT JSON_EXTRACT(@jg, CONCAT('$[', @i, ']')) INTO @g;
            SET @store = JSON_VALUE(@g, '$.f_store');
            IF (JSON_VALUE(@g, '$.f_isservice') = 0) THEN
                SET @needstore = 1;
            END IF;
            INSERT INTO `o_goods` (`f_id`, `f_header`, `f_body`, `f_store`, `f_goods`, `f_qty`,
                                   `f_price`, `f_total`, `f_tax`, `f_sign`, `f_taxdept`, `f_adgcode`, `f_row`,
                                   `f_storerec`, `f_discountfactor`, `f_discountmode`, `f_return`, `f_returnfrom`,
                                   `f_discountAmount`, `f_isservice`, `f_amountAccumulate`, `f_emarks`)
            VALUES (JSON_VALUE(@g, '$.f_id'), JSON_VALUE(@jh, '$.f_id'), '', JSON_VALUE(@g, '$.f_store'),
                    JSON_VALUE(@g, '$.f_goods'), JSON_VALUE(@g, '$.f_qty'),
                    JSON_VALUE(@g, '$.f_price'), JSON_VALUE(@g, '$.f_total'), JSON_VALUE(@g, '$.f_tax'),
                    JSON_VALUE(@g, '$.f_sign'), JSON_VALUE(@g, '$.f_taxdebt'), JSON_VALUE(@g, '$.f_adgcode'),
                    JSON_VALUE(@g, '$.f_row'),
                    JSON_VALUE(@g, '$.f_id'), JSON_VALUE(@g, '$.f_discountfactor'), JSON_VALUE(@g, '$.f_discountmode'),
                    JSON_VALUE(@g, '$.f_return'), JSON_VALUE(@g, '$.f_returnfrom'),
                    JSON_VALUE(@g, '$.f_discountamount'), JSON_VALUE(@g, '$.f_isservice'),
                    JSON_VALUE(@g, '$.f_amountaccumulate'), JSON_VALUE(@g, '$.f_emarks'));
            UPDATE a_store_sale
            SET f_qty=f_qty - JSON_VALUE(@g, '$.f_qty'),
                f_qtyprogram=f_qtyprogram - JSON_VALUE(@g, '$.f_qty')
            WHERE f_goods = JSON_VALUE(@g, '$.f_goods')
              AND f_store = JSON_VALUE(@g, '$.f_store');

            #sale gift card
            IF (@i = 0 AND JSON_VALUE(@jh, '$.f_saletype') = -1) THEN
                SELECT f_scancode INTO @scancode FROM c_goods WHERE f_id = JSON_VALUE(@g, '$.f_goods');
                SELECT f_id INTO @giftcardid FROM b_gift_card WHERE f_code = CONCAT('2211', @scancode);
                IF (@giftcardid IS NOT NULL) THEN
                    SELECT f_id
                    INTO @costumerid
                    FROM c_partners
                    WHERE f_phone = JSON_VALUE(params, '$.contact')
                    LIMIT 1;
                    IF (@costumerid IS NULL) THEN
                        INSERT INTO c_partners (f_phone, f_taxcode, f_contact, f_name)
                        VALUES (JSON_VALUE(params, '$.contact'), 'giftcard', JSON_VALUE(params, '$.organization'),
                                JSON_VALUE(params, '$.organization'));
                        SELECT LAST_INSERT_ID() INTO @costumerid;
                    END IF;

                    UPDATE b_gift_card
                    SET f_costumer=@costumerid,
                        f_datesaled=JSON_VALUE(@jh, '$.f_datecash'),
                        f_valid_until = DATE_ADD(CURRENT_DATE, INTERVAL 180 DAY)
                    WHERE f_id = @giftcardid;
                    INSERT INTO b_gift_card_history (f_card, f_trsale, f_amount)
                    VALUES (@giftcardid, JSON_VALUE(@jh, '$.f_id'), JSON_VALUE(@jh, '$.f_amounttotal'));
                ELSE
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GIFT ERROR 1';
                END IF;
            END IF;
            SET @i = @i + 1;
        END WHILE;

#gift card used
    SELECT JSON_VALUE(params, '$.giftcard') INTO @giftcard;
    IF (@giftcard > 0) THEN
        IF (JSON_VALUE(@jh, '$.f_amountprepaid') > 0) THEN
            INSERT INTO b_gift_card_history (f_card, f_trsale, f_amount)
            VALUES (@giftcard, JSON_VALUE(@jh, '$.f_id'), JSON_VALUE(@jh, '$.f_amountprepaid') * -1);
        ELSE
            SET @costumerid = NULL;
            SELECT f_id INTO @costumerid FROM c_partners WHERE f_phone = JSON_VALUE(params, '$.contact');
            IF (@costumerid IS NULL) THEN
                INSERT INTO c_partners (f_phone, f_taxcode, f_contact, f_name)
                VALUES (JSON_VALUE(params, '$.contact'), 'giftcard', JSON_VALUE(params, '$.organization'),
                        JSON_VALUE(params, '$.organization'));
                SELECT LAST_INSERT_ID() INTO @costumerid;
            END IF;
            UPDATE b_gift_card SET f_costumer=@costumerid, f_datesaled=CURRENT_DATE WHERE f_id = @giftcard;
            SELECT f_code INTO @cardcode FROM b_gift_card WHERE f_id = @giftcard;
            IF (@cardcode IS NOT NULL) THEN
                SELECT f_value INTO @f_value FROM b_cards_discount WHERE f_code = @cardcode;
                IF (@f_value IS NOT NULL) THEN
                    INSERT INTO b_gift_card_history (f_card, f_trsale, f_amount)
                    VALUES (@giftcard, JSON_VALUE(@jh, '$.f_id'), JSON_VALUE(@jh, '$.f_amounttotal') * @f_value);
                END IF;
            END IF;
        END IF;
    END IF;

    #create cash doc
#cash
    IF (JSON_VALUE(@jh, '$.f_amountcash') > 0) THEN
        SET @cashheader = UUID();
        INSERT INTO a_header (f_id, f_userid, f_state, f_type,
                              f_operator, f_date, f_createdate, f_createtime,
                              f_partner, f_amount, f_comment, f_payment, f_paid, f_currency, f_sessionid, f_body)
        VALUES (@cashheader, CONCAT(@prefix, @counter), 1, 5,
                JSON_VALUE(@jh, '$.f_cashier'), JSON_VALUE(@jh, '$.f_datecash'), CURRENT_DATE(), CURRENT_TIME(),
                0, JSON_VALUE(@jh, '$.f_amountcash'), CONCAT('Վաճառք ', @prefix, @counter), 0,
                0, JSON_VALUE(@jh, '$.f_currency'), NULL, '{}');
        INSERT INTO a_header_cash (f_id, f_cashin, f_cashout, f_oheader, f_related)
        VALUES (@cashheader, @cashid, 0, JSON_VALUE(@jh, '$.f_id'), 1);
        INSERT INTO e_cash (f_id, f_cash, f_sign, f_header, f_remarks, f_amount, f_base, f_row)
        VALUES (UUID(), @cashid, 1, @cashheader, CONCAT('Վաճառք ', @prefix, @counter),
                JSON_VALUE(@jh, '$.f_amountcash'), '', 0);

    END IF;
#nocash
    SET @amountcard = JSON_VALUE(@jh, '$.f_amountcard') + JSON_VALUE(@jh, '$.f_amountidram') +
                      JSON_VALUE(@jh, '$.f_amounttelcell');
    IF (@amountcard > 0) THEN
        SET @cashheader = UUID();
        INSERT INTO a_header (f_id, f_userid, f_state, f_type,
                              f_operator, f_date, f_createdate, f_createtime,
                              f_partner, f_amount, f_comment, f_payment, f_paid, f_currency, f_sessionid, f_body)
        VALUES (@cashheader, CONCAT(@prefix, @counter), 1, 5,
                JSON_VALUE(@jh, '$.f_cashier'), JSON_VALUE(@jh, '$.f_datecash'), CURRENT_DATE(), CURRENT_TIME(),
                0, @amountcard, CONCAT('Վաճառք ', @prefix, @counter), 0,
                0, JSON_VALUE(@jh, '$.f_currency'), NULL, '{}');
        INSERT INTO a_header_cash (f_id, f_cashin, f_cashout, f_oheader, f_related)
        VALUES (@cashheader, @nocashid, 0, JSON_VALUE(@jh, '$.f_id'), 1);
        INSERT INTO e_cash (f_id, f_cash, f_sign, f_header, f_remarks, f_amount, f_base, f_row)
        VALUES (UUID(), @nocashid, 1, @cashheader, CONCAT('Վաճառք ', @prefix, @counter), @amountcard, '', 0);

    END IF;
#debt or bank
    SET @amountdebt = JSON_VALUE(@jh, '$.f_amountbank') + JSON_VALUE(@jh, '$.f_amountdebt');
    IF (@amountdebt > 0) THEN
        INSERT INTO `b_clients_debts` (`f_date`, `f_costumer`, `f_order`,
                                       `f_cash`, `f_amount`, `f_govnumber`, `f_storedoc`,
                                       `f_currency`, `f_source`, `f_flag`)
        VALUES (JSON_VALUE(@jh, '$.f_datecash'), JSON_VALUE(@jh, '$.f_partner'), JSON_VALUE(@jh, '$.f_id'),
                NULL, @amountdebt * -1, NULL, NULL,
                JSON_VALUE(@jh, '$.f_currency'), 1, JSON_VALUE(@jh, '$.f_hall'));

    END IF;


#create store document 
    IF (@needstore = 1) THEN

        SELECT f_value
        INTO @f_donotcheckstore
        FROM s_settings_values s
                 LEFT JOIN s_settings_names n ON n.f_id = s.f_settings
        WHERE s.f_key = 86
          AND n.f_name = JSON_VALUE(params, '$.settings');
        INSERT INTO a_result(f_result) VALUES (params);

        SET @aheader_id = UUID();
        SELECT JSON_OBJECT(
                       'f_accepted', JSON_VALUE(@jh, '$.f_cashier'),
                       'f_passed', JSON_VALUE(@jh, '$.f_cashier'),
                       'f_invoice', '',
                       'f_invoicedate', NULL,
                       'f_storein', 0,
                       'f_storeout', CAST(@store AS INT),
                       'f_complectationcode', 0,
                       'f_complectationqty', 0,
                       'f_cashdoc', '',
                       'f_basedonsale', 1,
                       'f_saleuuid', JSON_VALUE(@jh, '$.f_id')
               )
        INTO @headerbody;
        SELECT JSON_OBJECT(
                       'f_id', @aheader_id,
                       'f_userid', 0,
                       'f_state', 1,
                       'f_type', 2,
                       'f_date', JSON_VALUE(@jh, '$.f_datecash'),
                       'f_operator', JSON_VALUE(@jh, '$.f_cashier'),
                       'f_partner', 0,
                       'f_amount', 0,
                       'f_currency', JSON_VALUE(@jh, '$.f_currency'),
                       'f_storein', 0,
                       'f_comment', CONCAT('Վաճառք ', @prefix, @counter),
                       'f_storeout', CAST(@store AS INT),
                       'f_reason', 4)
        INTO @aheader;
        SET @i = 0;
        SET @draft_goods = JSON_ARRAY();
        WHILE (@i < JSON_LENGTH(@jg))
            DO
                SELECT JSON_EXTRACT(@jg, CONCAT('$[', @i, ']')) INTO @g;
                IF (JSON_VALUE(@g, '$.f_isservice') = 0) THEN
                    SELECT JSON_OBJECT(
                                   'f_id', JSON_VALUE(@g, '$.f_id'),
                                   'f_goods', JSON_VALUE(@g, '$.f_goods'),
                                   'f_qty', JSON_VALUE(@g, '$.f_qty'),
                                   'f_price', 0,
                                   'f_validto', NULL,
                                   'f_comment', '',
                                   'f_row', @i)
                    INTO @d;
                    SELECT JSON_MERGE(@draft_goods, @d) INTO @draft_goods;
                END IF;
                SET @i = @i + 1;
            END WHILE;
        SET @store_session = UUID();
        SELECT JSON_OBJECT(
                       'notransaction', 1,
                       'session', @store_session,
                       'donotcheckstore', @f_donotcheckstore,
                       'header', JSON_DETAILED(@aheader),
                       'body', JSON_DETAILED(@headerbody),
                       'goods', JSON_DETAILED(@draft_goods)
               )
        INTO @headerparams;
        #INSERT INTO a_header_store (f_id, f_saleuuid, f_baseonsale, f_body) VALUES (@aheader_id, JSON_VALUE(@jh, '$.f_id'), 1, @headerparams);
        #CALL sf_create_store_document(@headerparams);
        #SELECT JSON_REPLACE(@headerparams, '$.header.f_state', 1) INTO @headerparams;

        CALL sf_create_store_document(@headerparams);

        #if failed prevoise operation due infucient quantity on store we looking on flag do_no_check_store
        #and if this flag was set to '1', we creating draft document
        IF (@f_donotcheckstore = '1') THEN

            SELECT JSON_DETAILED(f_result) INTO @store_result FROM a_result WHERE f_session = @store_session;
            IF (JSON_VALUE(@store_result, '$.status') = 0) THEN
                SELECT JSON_REPLACE(@headerparams, '$.header.f_state', 2) INTO @headerparams;
                CALL sf_create_store_document(@headerparams);
            END IF;
        END IF;

    END IF;

#finally update draft
    UPDATE o_draft_sale SET f_state=2, f_datefor=JSON_VALUE(@jd, '$.f_delivery') WHERE f_id = JSON_VALUE(@jh, '$.f_id');

    #SELECT CURRENT_TIMESTAMP() INTO @t2;
#INSERT INTO a_result (f_session, f_timestamp, f_done, f_elapsed, f_request, f_result) 
#	VALUES (JSON_VALUE(params, '$.session'), @t1, @t2, TIMESTAMPDIFF(SECOND, @t1, @t2), params, JSON_DETAILED(@result));
#SELECT JSON_VALUE(@result, '$.status') INTO @a;
#SIGNAL SQLSTATE '45000'
#SET MESSAGE_TEXT = @a;
    IF (JSON_VALUE(@result, '$.status') = 1) THEN
        COMMIT;
    ELSE
        ROLLBACK;
    END IF;


    SELECT CURRENT_TIMESTAMP() INTO @t2;
    INSERT INTO a_result (f_session, f_timestamp, f_done, f_elapsed, f_request, f_result)
    VALUES (JSON_VALUE(params, '$.session'), @t1, @t2, TIMESTAMPDIFF(SECOND, @t1, @t2), params,
            JSON_OBJECT('status', CAST(JSON_VALUE(@result, '$.status') AS unsigned), 'message',
                        JSON_VALUE(@result, '$.message')));


END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_complect.sql ==========
DROP FUNCTION IF EXISTS sf_store2_complect;
DELIMITER $$

CREATE FUNCTION sf_store2_complect(params longtext)
    RETURNS longtext
BEGIN
    DECLARE current_version int DEFAULT 0;
    DECLARE current_status int DEFAULT 0;
    DECLARE doc_uuid char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.doc_uuid');
    DECLARE store_out int DEFAULT CAST(JSON_VALUE(params, '$.doc_store_out') AS UNSIGNED);
    DECLARE store_in int DEFAULT CAST(JSON_VALUE(params, '$.doc_store_in') AS UNSIGNED);
    DECLARE doc_date datetime DEFAULT JSON_VALUE(params, '$.doc_date');
    DECLARE new_status int DEFAULT CAST(JSON_VALUE(params, '$.doc_status') AS UNSIGNED);
    DECLARE complect_goods int DEFAULT CAST(JSON_VALUE(params, '$.complect_goods') AS UNSIGNED);
    DECLARE complect_stock_id int DEFAULT 0;
    DECLARE complect_qty decimal(14, 4) DEFAULT CAST(JSON_VALUE(params, '$.complect_qty') AS DECIMAL(14, 4));
    DECLARE complect_row_id char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.complect_row_id');
    DECLARE doc_user_id char(8) DEFAULT JSON_VALUE(params, '$.doc_user_id');

    DECLARE curr_item_id INT;
    DECLARE curr_user_item_id INT;
    DECLARE curr_qty_needed DECIMAL(14, 4);
    DECLARE curr_row_id CHAR(36);
    DECLARE done INT DEFAULT FALSE;

    DECLARE take_qty DECIMAL(14, 4);
    DECLARE total_cost DECIMAL(14, 2) DEFAULT 0;
    DECLARE unit_price DECIMAL(14, 2) DEFAULT 0;
    DECLARE p_qty_arrived DECIMAL(14, 4);

    -- Resolve f_storeid inside the loop (JOIN inside CURSOR is unreliable on some MariaDB builds)
    DECLARE item_cursor CURSOR FOR
        SELECT jt.item_id, jt.qty, jt.row_id
        FROM JSON_TABLE(params, '$.items[*]'
                        COLUMNS (
                            item_id INT PATH '$.item_id',
                            qty DECIMAL(14, 4) PATH '$.qty',
                            row_id CHAR(36) PATH '$.id'
                            )
             ) AS jt;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    SET sql_safe_updates = 0;
    SET current_status = -1;

    -- Materialize the header first: locking a missing PK value would take a gap lock and
    -- deadlock against a parallel document inserting into the same gap.
    INSERT IGNORE INTO store_document (f_id, f_status, f_version) VALUES (doc_uuid, -1, 0);

    SELECT f_version, f_status
    INTO current_version, current_status
    FROM store_document
    WHERE f_id = doc_uuid FOR UPDATE;

    IF (current_version > 0 AND current_version <> CAST(JSON_VALUE(params, '$.doc_version') AS UNSIGNED)) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'version_error'));
    END IF;

    IF (IFNULL(complect_row_id, '') = '') THEN
        SET complect_row_id = UUID();
    END IF;

    SELECT IFNULL(NULLIF(f_storeid, 0), f_id)
    INTO complect_stock_id
    FROM c_goods
    WHERE f_id = complect_goods;
    IF (IFNULL(complect_stock_id, 0) = 0) THEN
        SET complect_stock_id = complect_goods;
    END IF;

    -- ===== REVERSE previous posting (product first, then materials) =====
    IF (current_status = 1) THEN
        -- Product sold to other docs?
        IF EXISTS (SELECT 1
                   FROM store_moves sm
                            JOIN store_stock ss ON sm.f_batch_id = ss.f_id
                   WHERE ss.f_doc = doc_uuid
                     AND ss.f_qty_in > 0
                     AND sm.f_doc <> doc_uuid) THEN
            RETURN JSON_COMPACT(JSON_OBJECT('status', 2, 'msg', 'already_sold_cannot_edit'));
        END IF;

        -- Restore negatives closed by product input
        -- Снимаем ровно то, что погасил этот документ: минус мог быть закрыт частично
        -- или несколькими приходами, поэтому обнулять партию нельзя.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        -- Remove product stock batches of this document
        DELETE FROM store_stock WHERE f_doc = doc_uuid AND f_qty_in > 0;
        DELETE FROM store_moves WHERE f_doc = doc_uuid AND f_qty_in > 0;

        -- Reverse materials write-off (same as sf_store2_output reverse)
        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;
    END IF;

    -- Emptied batches are dropped while this document's moves still exist: joining them keeps
    -- the statement on idx_moves_doc instead of scanning and locking the whole store_stock.
    IF (current_status = 1) THEN
        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> doc_uuid);
    END IF;

    DELETE FROM store_moves WHERE f_doc = doc_uuid;
    DELETE FROM store_stock WHERE f_doc = doc_uuid AND f_qty_in = 0 AND f_qty_left < 0;

    -- ===== Header =====
    INSERT INTO store_document (f_id, f_status, f_doc_type, f_doc_date, f_store_out, f_store_in, f_user_id, f_version,
                                f_sum, f_data)
    VALUES (doc_uuid, new_status, 4, doc_date, store_out, store_in, doc_user_id, 1, 0,
            JSON_EXTRACT(params, '$.doc_data'))
    ON DUPLICATE KEY UPDATE f_status    = VALUES(f_status),
                            f_doc_type  = VALUES(f_doc_type),
                            f_doc_date  = VALUES(f_doc_date),
                            f_store_out = VALUES(f_store_out),
                            f_store_in  = VALUES(f_store_in),
                            f_user_id   = VALUES(f_user_id),
                            f_data      = VALUES(f_data),
                            f_version   = f_version + 1;

    DELETE FROM store_user WHERE f_doc = doc_uuid;
    INSERT INTO store_user (f_id, f_doc, f_item_id, f_qty, f_comment, f_row)
    SELECT jt.row_uuid, doc_uuid, jt.item_id, jt.qty, jt.comment, jt.row
    FROM JSON_TABLE(params, '$.items[*]'
                    COLUMNS (row_uuid CHAR(36) PATH '$.id', item_id INT PATH '$.item_id',
                        qty DECIMAL(14, 4) PATH '$.qty', comment varchar(255) PATH '$.comment', row int PATH '$.row')
         ) AS jt;

    -- ===== Post: materials out + product in =====
    IF (new_status = 1) THEN
        SET total_cost = 0;
        SET done = FALSE;
        OPEN item_cursor;
        item_loop:
        LOOP
            FETCH item_cursor INTO curr_user_item_id, curr_qty_needed, curr_row_id;
            IF done THEN
                LEAVE item_loop;
            END IF;

            SELECT IFNULL(NULLIF(f_storeid, 0), f_id)
            INTO curr_item_id
            FROM c_goods
            WHERE f_id = curr_user_item_id;
            IF (IFNULL(curr_item_id, 0) = 0) THEN
                SET curr_item_id = curr_user_item_id;
            END IF;
            SET done = FALSE;

            fifo_block:
            BEGIN
                DECLARE b_done INT DEFAULT FALSE;
                DECLARE b_id CHAR(36);
                DECLARE b_qty_left DECIMAL(14, 4);
                DECLARE b_price DECIMAL(14, 2);

                DECLARE batch_cursor CURSOR FOR
                    SELECT f_id, f_qty_left, f_price
                    FROM store_stock
                    WHERE f_item_id = curr_item_id
                      AND f_store_id = store_out
                      AND f_qty_left > 0
                    ORDER BY f_batch_date ASC;

                DECLARE CONTINUE HANDLER FOR NOT FOUND SET b_done = TRUE;

                OPEN batch_cursor;
                batch_loop:
                LOOP
                    FETCH batch_cursor INTO b_id, b_qty_left, b_price;
                    IF b_done OR curr_qty_needed <= 0 THEN
                        LEAVE batch_loop;
                    END IF;

                    SET take_qty = LEAST(curr_qty_needed, b_qty_left);
                    UPDATE store_stock SET f_qty_left = f_qty_left - take_qty WHERE f_id = b_id;

                    INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_out,
                                             f_price, f_total)
                    VALUES (UUID(), doc_uuid, curr_row_id, b_id, store_out, curr_item_id, take_qty, b_price,
                            take_qty * b_price);

                    SET curr_qty_needed = curr_qty_needed - take_qty;
                    SET total_cost = total_cost + (take_qty * b_price);
                END LOOP;
                CLOSE batch_cursor;
            END fifo_block;

            SET done = FALSE;

            IF curr_qty_needed > 0 THEN
                RETURN JSON_COMPACT(JSON_OBJECT(
                        'status', 6,
                        'msg', 'insufficient_stock',
                        'item_id', curr_user_item_id,
                        'shortage', curr_qty_needed
                                    ));
            END IF;
        END LOOP;
        CLOSE item_cursor;

        UPDATE store_user su
            JOIN (SELECT f_doc_row_id, SUM(f_total) AS row_total, SUM(f_qty_out) AS row_qty
                  FROM store_moves
                  WHERE f_doc = doc_uuid
                    AND f_qty_out > 0
                  GROUP BY f_doc_row_id) AS sm
            ON su.f_id = sm.f_doc_row_id
        SET su.f_price = sm.row_total / NULLIF(sm.row_qty, 0),
            su.f_total = sm.row_total
        WHERE su.f_doc = doc_uuid;

        SET unit_price = CASE WHEN complect_qty > 0 THEN total_cost / complect_qty ELSE 0 END;
        SET p_qty_arrived = complect_qty;

        -- Close negatives of finished goods on store_in (stock goods via f_storeid)
        neg_block:
        BEGIN
            DECLARE done_neg INT DEFAULT FALSE;
            DECLARE neg_id CHAR(36);
            DECLARE neg_qty_abs DECIMAL(14, 4);
            DECLARE cur_neg CURSOR FOR SELECT f_id, ABS(f_qty_left)
                                       FROM store_stock
                                       WHERE f_item_id = complect_stock_id
                                         AND f_store_id = store_in
                                         AND f_qty_left < 0
                                       ORDER BY f_batch_date ASC;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_neg = TRUE;
            OPEN cur_neg;
            neg_loop:
            LOOP
                FETCH cur_neg INTO neg_id, neg_qty_abs;
                IF done_neg OR p_qty_arrived <= 0 THEN
                    LEAVE neg_loop;
                END IF;
                SET neg_qty_abs = CASE WHEN p_qty_arrived >= neg_qty_abs THEN neg_qty_abs ELSE p_qty_arrived END;

                INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in,
                                         f_price, f_total)
                VALUES (UUID(), doc_uuid, complect_row_id, neg_id, store_in, complect_stock_id, neg_qty_abs, unit_price,
                        neg_qty_abs * unit_price);

                -- Прибавляем, а не присваиваем: непокрытая часть минуса должна остаться.
                UPDATE store_stock
                SET f_qty_in     = f_qty_in + neg_qty_abs,
                    f_qty_left   = f_qty_left + neg_qty_abs,
                    f_price      = unit_price,
                    f_doc        = doc_uuid,
                    f_doc_row_id = complect_row_id
                WHERE f_id = neg_id;
                UPDATE store_moves SET f_price = unit_price, f_total = f_qty_out * unit_price WHERE f_batch_id = neg_id;

                SET p_qty_arrived = p_qty_arrived - neg_qty_abs;
            END LOOP;
            CLOSE cur_neg;
        END neg_block;

        IF p_qty_arrived > 0 THEN
            INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in, f_price,
                                     f_total)
            VALUES (UUID(), doc_uuid, complect_row_id, complect_row_id, store_in, complect_stock_id, p_qty_arrived,
                    unit_price, p_qty_arrived * unit_price);

            INSERT INTO store_stock (f_id, f_doc, f_doc_row_id, f_batch_date, f_store_id, f_item_id, f_qty_in,
                                     f_qty_left, f_price)
            VALUES (complect_row_id, doc_uuid, complect_row_id, doc_date, store_in, complect_stock_id, p_qty_arrived,
                    p_qty_arrived, unit_price);
        END IF;

        -- c_goods.f_lastinputprice is refreshed by the caller after COMMIT (see sf_store2_input).
    END IF;

    UPDATE store_document SET f_sum = total_cost WHERE f_id = doc_uuid;

    RETURN JSON_COMPACT(JSON_OBJECT(
            'status', 0,
            'cost', total_cost,
            'unit_price', unit_price,
            'complect_row_id', complect_row_id,
            'version', IFNULL(current_version, 0) + 1
                        ));
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_complect_delete.sql ==========
DROP FUNCTION IF EXISTS sf_store2_complect_delete;
DELIMITER $$

CREATE FUNCTION sf_store2_complect_delete(p_doc_uuid CHAR(36))
    RETURNS longtext
BEGIN
    DECLARE v_status INT;
    -- Probe without a lock first: FOR UPDATE on a missing PK value takes a gap lock.
    IF NOT EXISTS (SELECT 1 FROM store_document WHERE f_id = p_doc_uuid) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'document_not_found'));
    END IF;
    SELECT f_status INTO v_status FROM store_document WHERE f_id = p_doc_uuid FOR UPDATE;
    IF v_status IS NULL THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'document_not_found'));
    END IF;

    IF v_status = 1 THEN
        SET sql_safe_updates = 0;

        IF EXISTS (SELECT 1
                   FROM store_moves sm
                            JOIN store_stock ss ON sm.f_batch_id = ss.f_id
                   WHERE ss.f_doc = p_doc_uuid
                     AND ss.f_qty_in > 0
                     AND sm.f_doc <> p_doc_uuid) THEN
            RETURN JSON_COMPACT(JSON_OBJECT('status', 2, 'msg', 'already_sold_cannot_delete'));
        END IF;

        -- Reverse product input
        -- Снимаем ровно то, что погасил этот документ: минус мог быть закрыт частично
        -- или несколькими приходами, поэтому обнулять партию нельзя.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = p_doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> p_doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        DELETE FROM store_stock WHERE f_doc = p_doc_uuid AND f_qty_in > 0;
        DELETE FROM store_moves WHERE f_doc = p_doc_uuid AND f_qty_in > 0;

        -- Reverse materials output
        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = p_doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = p_doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = p_doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;

        DELETE ss
        FROM store_stock ss
        WHERE ss.f_doc = p_doc_uuid
          AND ss.f_qty_in = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves WHERE f_batch_id = ss.f_id AND f_doc <> p_doc_uuid);

        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = p_doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> p_doc_uuid);

        DELETE FROM store_moves WHERE f_doc = p_doc_uuid;
    END IF;

    DELETE FROM store_user WHERE f_doc = p_doc_uuid;
    DELETE FROM store_document WHERE f_id = p_doc_uuid;
    RETURN JSON_COMPACT(JSON_OBJECT('status', 0, 'msg', 'ok'));
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_input.sql ==========
DROP FUNCTION IF EXISTS sf_store2_input;
DELIMITER $$

CREATE FUNCTION sf_store2_input(params longtext)
    RETURNS longtext
BEGIN
    DECLARE current_version int DEFAULT 0;
    DECLARE current_status int DEFAULT 0;
    DECLARE doc_date datetime DEFAULT JSON_VALUE(params, '$.doc_date');
    DECLARE new_status int DEFAULT CAST(JSON_VALUE(params, '$.doc_status') AS UNSIGNED);
    DECLARE store_in int DEFAULT CAST(JSON_VALUE(params, '$.doc_store_in') AS UNSIGNED);
    DECLARE doc_uuid char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.doc_uuid');
    DECLARE doc_user_id char(16) DEFAULT JSON_VALUE(params, '$.doc_user_id');
    DECLARE create_user int DEFAULT CAST(JSON_VALUE(params, '$.doc_create_user') AS UNSIGNED);
    DECLARE cashbox_id int DEFAULT CAST(JSON_VALUE(params, '$.cashbox_id') AS unsigned);
    DECLARE payment_type_id int DEFAULT CAST(JSON_VALUE(params, '$.payment_type_id') AS UNSIGNED);
    DECLARE doc_sum decimal(14, 2) DEFAULT CAST(JSON_VALUE(params, '$.doc_sum') AS decimal(14, 2));
    DECLARE currency_id int DEFAULT CAST(JSON_VALUE(params, '$.currency_id') AS unsigned);
    DECLARE partner_id int DEFAULT CAST(JSON_VALUE(params, '$.doc_partner') AS unsigned);
    DECLARE paid_raw longtext DEFAULT JSON_VALUE(params, '$.paid_amount');
    DECLARE paid_amount decimal(14, 2) DEFAULT 0;
    DECLARE debt_amount decimal(14, 2) DEFAULT 0;
    DECLARE session_id int DEFAULT 0;

    DECLARE p_user_item_id INT;
    DECLARE p_item_id INT;
    DECLARE p_qty_arrived DECIMAL(14, 4);
    DECLARE p_price DECIMAL(14, 2);
    DECLARE p_row_uuid CHAR(36);
    DECLARE p_expire_date DATETIME;
    DECLARE done_items INT DEFAULT FALSE;

    -- Resolve f_storeid inside the loop (JOIN inside CURSOR is unreliable on some MariaDB builds)
    DECLARE cur_input CURSOR FOR
        SELECT jt.item_id, jt.qty, jt.price, jt.row_uuid, jt.expire_date
        FROM JSON_TABLE(params, '$.items[*]'
                        COLUMNS (
                            row_uuid CHAR(36) PATH '$.id',
                            item_id INT PATH '$.item_id',
                            qty DECIMAL(14, 4) PATH '$.qty',
                            price DECIMAL(14, 2) PATH '$.price',
                            expire_date DATETIME PATH '$.expire_date'
                            )) AS jt;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_items = TRUE;

    SET sql_safe_updates = 0;

    IF (paid_raw IS NULL OR paid_raw = '') THEN
        SET paid_amount = IF(IFNULL(cashbox_id, 0) > 0, doc_sum, 0);
    ELSE
        SET paid_amount = CAST(paid_raw AS decimal(14, 2));
    END IF;
    IF (paid_amount < 0) THEN
        SET paid_amount = 0;
    END IF;
    IF (paid_amount > doc_sum) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'paid_exceeds_sum');
    END IF;
    SET debt_amount = doc_sum - paid_amount;

    -- Materialize the header first: locking a missing PK value would take a gap lock and
    -- deadlock against a parallel document inserting into the same gap.
    INSERT IGNORE INTO store_document (f_id, f_status, f_version) VALUES (doc_uuid, -1, 0);

    SELECT f_version, f_status
    INTO current_version, current_status
    FROM store_document
    WHERE f_id = doc_uuid FOR
    UPDATE;

    IF (current_version > 0 AND current_version <> CAST(JSON_VALUE(params, '$.doc_version') AS UNSIGNED)) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'version_conflict');
    END IF;

    DELETE FROM b_clients_debts WHERE f_storedoc = doc_uuid;
    DELETE FROM cash_debts WHERE f_doc_uuid = doc_uuid;
    DELETE FROM cash_operations WHERE f_order_id = doc_uuid;
    -- Реверс старого проведения (если был статус 1)
    IF (current_status = 1) THEN
        -- Снимаем погашение чужих минусов (f_doc_row_id <> f_batch_id — признак погашения).
        -- Вычитаем ровно то, что погасил этот документ: минус мог быть закрыт частично
        -- или несколькими приходами, и обнулять партию нельзя.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        -- Из своих партий могли уже списать другие документы. Такую партию нельзя просто
        -- удалить: их расходы остались бы без партии. Переносим списанное на отдельный
        -- минус, а саму партию удаляем — строка прихода перепроведётся заново.
        own_batches:
        BEGIN
            DECLARE done_own INT DEFAULT FALSE;
            DECLARE o_id CHAR(36);
            DECLARE o_consumed DECIMAL(14, 4);
            DECLARE o_store INT;
            DECLARE o_item INT;
            DECLARE o_date DATETIME;
            DECLARE o_hole CHAR(36);
            DECLARE cur_own CURSOR FOR
                SELECT ss.f_id, ss.f_qty_in - ss.f_qty_left, ss.f_store_id, ss.f_item_id, ss.f_batch_date
                FROM store_stock ss
                WHERE ss.f_doc = doc_uuid
                  AND ss.f_id = ss.f_doc_row_id
                  AND EXISTS (SELECT 1 FROM store_moves sm
                              WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> doc_uuid);
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_own = TRUE;

            OPEN cur_own;
            own_loop:
            LOOP
                FETCH cur_own INTO o_id, o_consumed, o_store, o_item, o_date;
                IF done_own THEN LEAVE own_loop; END IF;
                IF o_consumed > 0 THEN
                    SET o_hole = UUID();
                    INSERT INTO store_stock (f_id, f_doc, f_doc_row_id, f_batch_date, f_store_id, f_item_id,
                                             f_qty_in, f_qty_left, f_price)
                    VALUES (o_hole, NULL, NULL, o_date, o_store, o_item, 0, -o_consumed, 0);
                    UPDATE store_moves SET f_batch_id = o_hole
                    WHERE f_batch_id = o_id AND f_doc <> doc_uuid;
                END IF;
            END LOOP;
            CLOSE cur_own;
            SET done_items = FALSE;
        END own_batches;

        DELETE FROM store_moves WHERE f_doc = doc_uuid;
        DELETE FROM store_stock WHERE f_doc = doc_uuid;
    END IF;

    INSERT INTO store_document (f_id, f_user_id, f_status, f_doc_type, f_doc_date, f_store_in, f_sum, f_partner,
                                f_version, f_data)
    VALUES (doc_uuid, doc_user_id, new_status, CAST(JSON_VALUE(params, '$.doc_type') AS UNSIGNED), doc_date, store_in,
            CAST(JSON_VALUE(params, '$.doc_sum') AS DECIMAL(14, 2)), partner_id, IFNULL(current_version, 0) + 1,
            JSON_EXTRACT(params, '$.doc_data'))
    ON DUPLICATE KEY UPDATE f_status   = VALUES(f_status),
                            f_user_id  = doc_user_id,
                            f_doc_type = VALUES(f_doc_type),
                            f_doc_date = VALUES(f_doc_date),
                            f_store_in = store_in,
                            f_sum      = VALUES(f_sum),
                            f_partner  = partner_id,
                            f_version  = f_version + 1,
                            f_data     = VALUES(f_data);

    DELETE FROM store_user WHERE f_doc = doc_uuid;
    INSERT INTO store_user (f_id, f_doc, f_item_id, f_qty, f_price, f_total, f_comment, f_row)
    SELECT row_uuid,
           doc_uuid,
           item_id,
           qty,
           price,
           qty * price,
           comment,
           `row`
    FROM JSON_TABLE(params, '$.items[*]'
                    COLUMNS (row_uuid CHAR(36) PATH '$.id', item_id INT PATH '$.item_id', qty DECIMAL(14, 4) PATH '$.qty', price DECIMAL(14, 2) PATH '$.price', comment varchar(255) PATH '$.comment', `row` int PATH '$.row')) AS jt;

    IF (new_status = 1) THEN
        IF (paid_amount > 0) THEN
            IF (IFNULL(cashbox_id, 0) <= 0 OR IFNULL(payment_type_id, 0) <= 0) THEN
                RETURN JSON_OBJECT('status', 1, 'msg', 'cashbox_required_for_paid');
            END IF;
            SET session_id = IFNULL((SELECT f_id
                                     FROM cash_session
                                     WHERE f_state = 1
                                       AND f_cashbox_id = cashbox_id
                                     ORDER BY f_id DESC
                                     LIMIT 1), 0);
            INSERT INTO cash_operations (f_cashbox_id, f_session_id, f_order_id, f_user, f_operation_type,
                                         f_payment_type_id, f_datetime, f_credit, f_currency_id, f_affects_float)
            VALUES (cashbox_id, NULLIF(session_id, 0), doc_uuid, create_user, 3, payment_type_id, doc_date,
                    paid_amount, IFNULL(currency_id, 1), IF(payment_type_id = 1, 1, 0));
            -- Cash purchase reduces drawer float when a shift is open on this cashbox.
            IF (payment_type_id = 1 AND IFNULL(session_id, 0) > 0) THEN
                UPDATE cash_session
                SET f_amount_expected = f_amount_expected - paid_amount
                WHERE f_id = session_id;
            END IF;
        END IF;
        IF (debt_amount > 0) THEN
            IF (IFNULL(partner_id, 0) <= 0) THEN
                RETURN JSON_OBJECT('status', 1, 'msg', 'partner_required_for_debt');
            END IF;
            INSERT INTO cash_debts (f_date, f_partner, f_doc_type, f_doc_uuid, f_credit, f_debit, f_currency_id)
            VALUES (doc_date, partner_id, 1, doc_uuid, debt_amount, 0, IFNULL(currency_id, 1));
        END IF;

        SET done_items = FALSE;
        OPEN cur_input;
        input_loop:
        LOOP
            FETCH cur_input INTO p_user_item_id, p_qty_arrived, p_price, p_row_uuid, p_expire_date;
            IF done_items THEN LEAVE input_loop; END IF;

            SELECT IFNULL(NULLIF(f_storeid, 0), f_id)
            INTO p_item_id
            FROM c_goods
            WHERE f_id = p_user_item_id;
            IF (IFNULL(p_item_id, 0) = 0) THEN
                SET p_item_id = p_user_item_id;
            END IF;
            SET done_items = FALSE;

            block_neg:
            BEGIN
                DECLARE done_neg INT DEFAULT FALSE;
                DECLARE neg_id CHAR(36);
                DECLARE neg_qty_abs DECIMAL(14, 4);
                DECLARE cur_neg CURSOR FOR SELECT f_id, ABS(f_qty_left)
                                           FROM store_stock
                                           WHERE f_item_id = p_item_id
                                             AND f_store_id = store_in
                                             AND f_qty_left < 0
                                           ORDER BY f_batch_date ASC;
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_neg = TRUE;
                OPEN cur_neg;
                neg_loop:
                LOOP
                    FETCH cur_neg INTO neg_id, neg_qty_abs;
                    IF done_neg OR p_qty_arrived <= 0 THEN LEAVE neg_loop; END IF;

                    SET neg_qty_abs = CASE WHEN p_qty_arrived >= neg_qty_abs THEN neg_qty_abs ELSE p_qty_arrived END;

                    -- Записываем связь: приход закрыл этот конкретный минус
                    INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in,
                                             f_price, f_total)
                    VALUES (UUID(), doc_uuid, p_row_uuid, neg_id, store_in, p_item_id, neg_qty_abs, p_price,
                            neg_qty_abs * p_price);

                    -- Прибавляем, а не присваиваем: минус мог быть больше прихода,
                    -- тогда непокрытый остаток должен сохраниться отрицательным.
                    UPDATE store_stock
                    SET f_qty_in     = f_qty_in + neg_qty_abs,
                        f_qty_left   = f_qty_left + neg_qty_abs,
                        f_price      = p_price,
                        f_doc        = doc_uuid,
                        f_doc_row_id = p_row_uuid
                    WHERE f_id = neg_id;
                    UPDATE store_moves SET f_price = p_price, f_total = f_qty_out * p_price WHERE f_batch_id = neg_id;

                    SET p_qty_arrived = p_qty_arrived - neg_qty_abs;
                END LOOP;
                CLOSE cur_neg;
            END block_neg;

            -- Движение на партию p_row_uuid только на остаток после погашения минусов (иначе 20+1 в store_moves).
            IF p_qty_arrived > 0 THEN
                INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in,
                                         f_price,
                                         f_total)
                VALUES (UUID(), doc_uuid, p_row_uuid, p_row_uuid, store_in, p_item_id, p_qty_arrived, p_price,
                        p_qty_arrived * p_price);

                INSERT INTO store_stock (f_id, f_doc, f_doc_row_id, f_batch_date, f_expiry_date, f_store_id, f_item_id,
                                         f_qty_in, f_qty_left, f_price)
                VALUES (p_row_uuid, doc_uuid, p_row_uuid, doc_date, p_expire_date, store_in, p_item_id, p_qty_arrived,
                        p_qty_arrived, p_price);
            END IF;
        END LOOP;
        CLOSE cur_input;
    END IF;

    -- c_goods.f_lastinputprice is refreshed by the caller after COMMIT: keeping the catalog
    -- out of this transaction removes a hot lock shared with menu/goods editors.

    RETURN JSON_OBJECT('status', 0, 'version', IFNULL(current_version, 0) + 1, 'paid_amount', paid_amount);
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_input_set_paid.sql ==========
DROP FUNCTION IF EXISTS sf_store2_input_set_paid;
DELIMITER $$

-- Update paid/debt split on a posted store input without touching stock.
CREATE FUNCTION sf_store2_input_set_paid(params longtext)
    RETURNS longtext
BEGIN
    DECLARE doc_uuid char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.doc_uuid');
    DECLARE create_user int DEFAULT CAST(JSON_VALUE(params, '$.doc_create_user') AS UNSIGNED);
    DECLARE cashbox_id int DEFAULT CAST(JSON_VALUE(params, '$.cashbox_id') AS unsigned);
    DECLARE payment_type_id int DEFAULT CAST(JSON_VALUE(params, '$.payment_type_id') AS UNSIGNED);
    DECLARE currency_id int DEFAULT CAST(JSON_VALUE(params, '$.currency_id') AS unsigned);
    DECLARE paid_amount decimal(14, 2) DEFAULT CAST(JSON_VALUE(params, '$.paid_amount') AS decimal(14, 2));
    DECLARE doc_version int DEFAULT CAST(JSON_VALUE(params, '$.doc_version') AS UNSIGNED);

    DECLARE current_version int DEFAULT 0;
    DECLARE current_status int DEFAULT 0;
    DECLARE doc_sum decimal(14, 2) DEFAULT 0;
    DECLARE partner_id int DEFAULT 0;
    DECLARE doc_date datetime;
    DECLARE debt_amount decimal(14, 2) DEFAULT 0;
    DECLARE doc_data longtext;
    DECLARE session_id int DEFAULT 0;
    DECLARE old_session_id int DEFAULT 0;
    DECLARE old_float_credit decimal(14, 2) DEFAULT 0;

    SET sql_safe_updates = 0;

    IF NOT EXISTS (SELECT 1 FROM store_document WHERE f_id = doc_uuid) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_found');
    END IF;

    SELECT f_version, f_status, f_sum, f_partner, f_doc_date, f_data
    INTO current_version, current_status, doc_sum, partner_id, doc_date, doc_data
    FROM store_document
    WHERE f_id = doc_uuid FOR UPDATE;

    IF (current_status <> 1) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_posted');
    END IF;

    IF (current_version <> doc_version) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'version_conflict');
    END IF;

    IF (paid_amount IS NULL OR paid_amount < 0) THEN
        SET paid_amount = 0;
    END IF;
    IF (paid_amount > doc_sum) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'paid_exceeds_sum');
    END IF;
    SET debt_amount = doc_sum - paid_amount;

    IF (paid_amount > 0 AND (IFNULL(cashbox_id, 0) <= 0 OR IFNULL(payment_type_id, 0) <= 0)) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'cashbox_required_for_paid');
    END IF;
    IF (debt_amount > 0 AND IFNULL(partner_id, 0) <= 0) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'partner_required_for_debt');
    END IF;

    -- Reverse prior cash-float impact before replacing purchase payment lines.
    BEGIN
        DECLARE done_rev INT DEFAULT FALSE;
        DECLARE cur_rev CURSOR FOR
            SELECT f_session_id, COALESCE(SUM(f_credit), 0)
            FROM cash_operations
            WHERE f_order_id = doc_uuid
              AND f_session_id > 0
              AND f_affects_float = 1
            GROUP BY f_session_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_rev = TRUE;
        OPEN cur_rev;
        rev_loop:
        LOOP
            FETCH cur_rev INTO old_session_id, old_float_credit;
            IF done_rev THEN LEAVE rev_loop; END IF;
            UPDATE cash_session
            SET f_amount_expected = f_amount_expected + old_float_credit
            WHERE f_id = old_session_id;
        END LOOP;
        CLOSE cur_rev;
    END;

    DELETE FROM cash_operations WHERE f_order_id = doc_uuid;
    DELETE FROM cash_debts WHERE f_doc_uuid = doc_uuid;

    IF (paid_amount > 0) THEN
        SET session_id = IFNULL((SELECT f_id
                                 FROM cash_session
                                 WHERE f_state = 1
                                   AND f_cashbox_id = cashbox_id
                                 ORDER BY f_id DESC
                                 LIMIT 1), 0);
        INSERT INTO cash_operations (f_cashbox_id, f_session_id, f_order_id, f_user, f_operation_type,
                                     f_payment_type_id, f_datetime, f_credit, f_currency_id, f_affects_float)
        VALUES (cashbox_id, NULLIF(session_id, 0), doc_uuid, create_user, 3, payment_type_id, doc_date,
                paid_amount, IFNULL(currency_id, 1), IF(payment_type_id = 1, 1, 0));
        IF (payment_type_id = 1 AND IFNULL(session_id, 0) > 0) THEN
            UPDATE cash_session
            SET f_amount_expected = f_amount_expected - paid_amount
            WHERE f_id = session_id;
        END IF;
    END IF;
    IF (debt_amount > 0) THEN
        INSERT INTO cash_debts (f_date, f_partner, f_doc_type, f_doc_uuid, f_credit, f_debit, f_currency_id)
        VALUES (doc_date, partner_id, 1, doc_uuid, debt_amount, 0, IFNULL(currency_id, 1));
    END IF;

    SET doc_data = JSON_SET(
            IFNULL(doc_data, '{}'),
            '$.paid_amount', paid_amount,
            '$.cashbox_id', IFNULL(cashbox_id, 0),
            '$.payment_type_id', IFNULL(payment_type_id, 0),
            '$.currency_id', IFNULL(currency_id, 1)
        );

    UPDATE store_document
    SET f_data    = doc_data,
        f_version = f_version + 1
    WHERE f_id = doc_uuid;

    RETURN JSON_OBJECT('status', 0, 'version', current_version + 1, 'paid_amount', paid_amount);
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_move.sql ==========
DROP FUNCTION IF EXISTS sf_store2_move;
DELIMITER $$

CREATE FUNCTION sf_store2_move(params longtext)
    RETURNS longtext
BEGIN
    DECLARE current_version int DEFAULT 0;
    DECLARE current_status int DEFAULT 0;
    DECLARE doc_uuid char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.doc_uuid');
    DECLARE store_out int DEFAULT CAST(JSON_VALUE(params, '$.doc_store_out') AS UNSIGNED);
    DECLARE store_in int DEFAULT CAST(JSON_VALUE(params, '$.doc_store_in') AS UNSIGNED);
    DECLARE doc_date datetime DEFAULT JSON_VALUE(params, '$.doc_date');
    DECLARE new_status int DEFAULT CAST(JSON_VALUE(params, '$.doc_status') AS UNSIGNED);
    DECLARE doc_user_id char(8) DEFAULT JSON_VALUE(params, '$.doc_user_id');

    DECLARE curr_item_id INT;
    DECLARE curr_user_item_id INT;
    DECLARE curr_qty_needed DECIMAL(14, 4);
    DECLARE curr_qty_orig DECIMAL(14, 4);
    DECLARE curr_row_id CHAR(36);
    DECLARE done INT DEFAULT FALSE;

    DECLARE take_qty DECIMAL(14, 4);
    DECLARE total_cost DECIMAL(14, 2) DEFAULT 0;
    DECLARE row_cost DECIMAL(14, 2);
    DECLARE unit_price DECIMAL(14, 2);
    DECLARE p_qty_arrived DECIMAL(14, 4);

    -- Resolve f_storeid inside the loop (JOIN inside CURSOR is unreliable on some MariaDB builds)
    DECLARE item_cursor CURSOR FOR
        SELECT jt.item_id, jt.qty, jt.row_id
        FROM JSON_TABLE(params, '$.items[*]'
                        COLUMNS (
                            item_id INT PATH '$.item_id',
                            qty DECIMAL(14, 4) PATH '$.qty',
                            row_id CHAR(36) PATH '$.id'
                            )
             ) AS jt;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    SET sql_safe_updates = 0;
    SET current_status = -1;

    IF (IFNULL(store_out, 0) = 0 OR IFNULL(store_in, 0) = 0) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 4, 'msg', 'stores_required'));
    END IF;
    IF (store_out = store_in) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 5, 'msg', 'stores_must_differ'));
    END IF;

    -- Materialize the header first: locking a missing PK value would take a gap lock and
    -- deadlock against a parallel document inserting into the same gap.
    INSERT IGNORE INTO store_document (f_id, f_status, f_version) VALUES (doc_uuid, -1, 0);

    SELECT f_version, f_status
    INTO current_version, current_status
    FROM store_document
    WHERE f_id = doc_uuid FOR UPDATE;

    IF (current_version > 0 AND current_version <> CAST(JSON_VALUE(params, '$.doc_version') AS UNSIGNED)) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'version_error'));
    END IF;

    -- ===== REVERSE previous posting (input first, then output) =====
    IF (current_status = 1) THEN
        IF EXISTS (SELECT 1
                   FROM store_moves sm
                            JOIN store_stock ss ON sm.f_batch_id = ss.f_id
                   WHERE ss.f_doc = doc_uuid
                     AND ss.f_qty_in > 0
                     AND sm.f_doc <> doc_uuid) THEN
            RETURN JSON_COMPACT(JSON_OBJECT('status', 2, 'msg', 'already_sold_cannot_edit'));
        END IF;

        -- Снимаем ровно то, что погасил этот документ: минус мог быть закрыт частично
        -- или несколькими приходами, поэтому обнулять партию нельзя.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        DELETE FROM store_stock WHERE f_doc = doc_uuid AND f_qty_in > 0;
        DELETE FROM store_moves WHERE f_doc = doc_uuid AND f_qty_in > 0;

        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;
    END IF;

    -- Emptied batches are dropped while this document's moves still exist: joining them keeps
    -- the statement on idx_moves_doc instead of scanning and locking the whole store_stock.
    IF (current_status = 1) THEN
        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> doc_uuid);
    END IF;

    DELETE FROM store_moves WHERE f_doc = doc_uuid;
    DELETE FROM store_stock WHERE f_doc = doc_uuid AND f_qty_in = 0 AND f_qty_left < 0;

    -- ===== Header =====
    INSERT INTO store_document (f_id, f_status, f_doc_type, f_doc_date, f_store_out, f_store_in, f_user_id, f_version,
                                f_sum, f_data)
    VALUES (doc_uuid, new_status, 3, doc_date, store_out, store_in, doc_user_id, 1, 0,
            JSON_EXTRACT(params, '$.doc_data'))
    ON DUPLICATE KEY UPDATE f_status    = VALUES(f_status),
                            f_doc_type  = VALUES(f_doc_type),
                            f_doc_date  = VALUES(f_doc_date),
                            f_store_out = VALUES(f_store_out),
                            f_store_in  = VALUES(f_store_in),
                            f_user_id   = VALUES(f_user_id),
                            f_data      = VALUES(f_data),
                            f_version   = f_version + 1;

    DELETE FROM store_user WHERE f_doc = doc_uuid;
    INSERT INTO store_user (f_id, f_doc, f_item_id, f_qty, f_comment, f_row)
    SELECT jt.row_uuid, doc_uuid, jt.item_id, jt.qty, jt.comment, jt.row
    FROM JSON_TABLE(params, '$.items[*]'
                    COLUMNS (row_uuid CHAR(36) PATH '$.id', item_id INT PATH '$.item_id',
                        qty DECIMAL(14, 4) PATH '$.qty', comment varchar(255) PATH '$.comment', row int PATH '$.row')
         ) AS jt;

    -- ===== Post: out from store_out + in to store_in =====
    IF (new_status = 1) THEN
        SET total_cost = 0;
        SET done = FALSE;
        OPEN item_cursor;
        item_loop:
        LOOP
            FETCH item_cursor INTO curr_user_item_id, curr_qty_needed, curr_row_id;
            IF done THEN
                LEAVE item_loop;
            END IF;

            SELECT IFNULL(NULLIF(f_storeid, 0), f_id)
            INTO curr_item_id
            FROM c_goods
            WHERE f_id = curr_user_item_id;
            IF (IFNULL(curr_item_id, 0) = 0) THEN
                SET curr_item_id = curr_user_item_id;
            END IF;
            SET done = FALSE;

            SET curr_qty_orig = curr_qty_needed;
            SET row_cost = 0;

            fifo_block:
            BEGIN
                DECLARE b_done INT DEFAULT FALSE;
                DECLARE b_id CHAR(36);
                DECLARE b_qty_left DECIMAL(14, 4);
                DECLARE b_price DECIMAL(14, 2);

                DECLARE batch_cursor CURSOR FOR
                    SELECT f_id, f_qty_left, f_price
                    FROM store_stock
                    WHERE f_item_id = curr_item_id
                      AND f_store_id = store_out
                      AND f_qty_left > 0
                    ORDER BY f_batch_date ASC;

                DECLARE CONTINUE HANDLER FOR NOT FOUND SET b_done = TRUE;

                OPEN batch_cursor;
                batch_loop:
                LOOP
                    FETCH batch_cursor INTO b_id, b_qty_left, b_price;
                    IF b_done OR curr_qty_needed <= 0 THEN
                        LEAVE batch_loop;
                    END IF;

                    SET take_qty = LEAST(curr_qty_needed, b_qty_left);
                    UPDATE store_stock SET f_qty_left = f_qty_left - take_qty WHERE f_id = b_id;

                    INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_out,
                                             f_price, f_total)
                    VALUES (UUID(), doc_uuid, curr_row_id, b_id, store_out, curr_item_id, take_qty, b_price,
                            take_qty * b_price);

                    SET curr_qty_needed = curr_qty_needed - take_qty;
                    SET row_cost = row_cost + (take_qty * b_price);
                END LOOP;
                CLOSE batch_cursor;
            END fifo_block;

            SET done = FALSE;

            IF curr_qty_needed > 0 THEN
                RETURN JSON_COMPACT(JSON_OBJECT(
                        'status', 6,
                        'msg', 'insufficient_stock',
                        'item_id', curr_user_item_id,
                        'shortage', curr_qty_needed
                                    ));
            END IF;

            SET unit_price = CASE WHEN curr_qty_orig > 0 THEN row_cost / curr_qty_orig ELSE 0 END;
            SET p_qty_arrived = curr_qty_orig;
            SET total_cost = total_cost + row_cost;

            UPDATE store_user
            SET f_price = unit_price,
                f_total = row_cost
            WHERE f_id = curr_row_id AND f_doc = doc_uuid;

            -- Close negatives on store_in
            neg_block:
            BEGIN
                DECLARE done_neg INT DEFAULT FALSE;
                DECLARE neg_id CHAR(36);
                DECLARE neg_qty_abs DECIMAL(14, 4);
                DECLARE cur_neg CURSOR FOR SELECT f_id, ABS(f_qty_left)
                                           FROM store_stock
                                           WHERE f_item_id = curr_item_id
                                             AND f_store_id = store_in
                                             AND f_qty_left < 0
                                           ORDER BY f_batch_date ASC;
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_neg = TRUE;
                OPEN cur_neg;
                neg_loop:
                LOOP
                    FETCH cur_neg INTO neg_id, neg_qty_abs;
                    IF done_neg OR p_qty_arrived <= 0 THEN
                        LEAVE neg_loop;
                    END IF;
                    SET neg_qty_abs = CASE WHEN p_qty_arrived >= neg_qty_abs THEN neg_qty_abs ELSE p_qty_arrived END;

                    INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in,
                                             f_price, f_total)
                    VALUES (UUID(), doc_uuid, curr_row_id, neg_id, store_in, curr_item_id, neg_qty_abs, unit_price,
                            neg_qty_abs * unit_price);

                    -- Прибавляем, а не присваиваем: непокрытая часть минуса должна остаться.
                    UPDATE store_stock
                    SET f_qty_in     = f_qty_in + neg_qty_abs,
                        f_qty_left   = f_qty_left + neg_qty_abs,
                        f_price      = unit_price,
                        f_doc        = doc_uuid,
                        f_doc_row_id = curr_row_id
                    WHERE f_id = neg_id;
                    UPDATE store_moves SET f_price = unit_price, f_total = f_qty_out * unit_price WHERE f_batch_id = neg_id;

                    SET p_qty_arrived = p_qty_arrived - neg_qty_abs;
                END LOOP;
                CLOSE cur_neg;
            END neg_block;

            IF p_qty_arrived > 0 THEN
                INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_in, f_price,
                                         f_total)
                VALUES (UUID(), doc_uuid, curr_row_id, curr_row_id, store_in, curr_item_id, p_qty_arrived,
                        unit_price, p_qty_arrived * unit_price);

                INSERT INTO store_stock (f_id, f_doc, f_doc_row_id, f_batch_date, f_store_id, f_item_id, f_qty_in,
                                         f_qty_left, f_price)
                VALUES (curr_row_id, doc_uuid, curr_row_id, doc_date, store_in, curr_item_id, p_qty_arrived,
                        p_qty_arrived, unit_price);
            END IF;
        END LOOP;
        CLOSE item_cursor;
    END IF;

    UPDATE store_document SET f_sum = total_cost WHERE f_id = doc_uuid;

    RETURN JSON_COMPACT(JSON_OBJECT(
            'status', 0,
            'cost', total_cost,
            'version', IFNULL(current_version, 0) + 1
                        ));
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_move_delete.sql ==========
DROP FUNCTION IF EXISTS sf_store2_move_delete;
DELIMITER $$

CREATE FUNCTION sf_store2_move_delete(p_doc_uuid CHAR(36))
    RETURNS longtext
BEGIN
    DECLARE v_status INT;
    -- Probe without a lock first: FOR UPDATE on a missing PK value takes a gap lock.
    IF NOT EXISTS (SELECT 1 FROM store_document WHERE f_id = p_doc_uuid) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'document_not_found'));
    END IF;
    SELECT f_status INTO v_status FROM store_document WHERE f_id = p_doc_uuid FOR UPDATE;
    IF v_status IS NULL THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'document_not_found'));
    END IF;

    IF v_status = 1 THEN
        SET sql_safe_updates = 0;

        IF EXISTS (SELECT 1
                   FROM store_moves sm
                            JOIN store_stock ss ON sm.f_batch_id = ss.f_id
                   WHERE ss.f_doc = p_doc_uuid
                     AND ss.f_qty_in > 0
                     AND sm.f_doc <> p_doc_uuid) THEN
            RETURN JSON_COMPACT(JSON_OBJECT('status', 2, 'msg', 'already_sold_cannot_delete'));
        END IF;

        -- Снимаем ровно то, что погасил этот документ: минус мог быть закрыт частично
        -- или несколькими приходами, поэтому обнулять партию нельзя.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = p_doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> p_doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        DELETE FROM store_stock WHERE f_doc = p_doc_uuid AND f_qty_in > 0;
        DELETE FROM store_moves WHERE f_doc = p_doc_uuid AND f_qty_in > 0;

        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = p_doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = p_doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = p_doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;

        DELETE ss
        FROM store_stock ss
        WHERE ss.f_doc = p_doc_uuid
          AND ss.f_qty_in = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves WHERE f_batch_id = ss.f_id AND f_doc <> p_doc_uuid);

        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = p_doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> p_doc_uuid);

        DELETE FROM store_moves WHERE f_doc = p_doc_uuid;
    END IF;

    DELETE FROM store_user WHERE f_doc = p_doc_uuid;
    DELETE FROM store_document WHERE f_id = p_doc_uuid;
    RETURN JSON_COMPACT(JSON_OBJECT('status', 0, 'msg', 'ok'));
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_output.sql ==========
DROP FUNCTION IF EXISTS sf_store2_output;
DELIMITER $$

CREATE FUNCTION sf_store2_output(params longtext)
    RETURNS longtext
BEGIN
    DECLARE current_version int DEFAULT 0;
    DECLARE current_status int DEFAULT 0;
    DECLARE doc_uuid char(36) COLLATE latin1_general_ci DEFAULT JSON_VALUE(params, '$.doc_uuid');
    DECLARE store_id int DEFAULT JSON_VALUE(params, '$.doc_store_out');
    DECLARE doc_date datetime DEFAULT JSON_VALUE(params, '$.doc_date');
    DECLARE new_status int DEFAULT CAST(JSON_VALUE(params, '$.doc_status') AS UNSIGNED);

    DECLARE curr_item_id INT;
    DECLARE curr_user_item_id INT;
    DECLARE curr_qty_needed DECIMAL(14, 4);
    DECLARE curr_row_id CHAR(36);
    DECLARE done INT DEFAULT FALSE;

    DECLARE v_neg_id CHAR(36);
    DECLARE take_qty DECIMAL(14, 4);
    DECLARE total_cost DECIMAL(14, 2) DEFAULT 0;
    DECLARE last_input_price DECIMAL(14, 2);

    -- Resolve f_storeid inside the loop (JOIN inside CURSOR is unreliable on some MariaDB builds)
    DECLARE item_cursor CURSOR FOR
        SELECT jt.item_id, jt.qty, jt.row_id
        FROM JSON_TABLE(params, '$.items[*]'
                        COLUMNS (
                            item_id INT PATH '$.item_id',
                            qty DECIMAL(14, 4) PATH '$.qty',
                            row_id CHAR(36) PATH '$.id'
                            )
             ) AS jt;

    -- Обработчик для основного курсора
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- 1. Получаем текущее состояние документа
    SET current_status = -1;

    -- Materialize the header first: locking a missing PK value would take a gap lock and
    -- deadlock against a parallel document inserting into the same gap.
    INSERT IGNORE INTO store_document (f_id, f_status, f_version) VALUES (doc_uuid, -1, 0);

    SELECT f_version, f_status
    INTO current_version, current_status
    FROM store_document
    WHERE f_id = doc_uuid FOR
    UPDATE;

    -- Проверка версии
    IF (current_version > 0 AND current_version <> CAST(JSON_VALUE(params, '$.doc_version') AS UNSIGNED)) THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'version_error'));
    END IF;

    -- 2. РЕВЕРС (как sf_store2_output_delete): минус+приход — вернуть qmerge на основную партию; остальное — в f_qty_left
    IF (current_status = 1) THEN
        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;
    END IF;

    -- Emptied batches are dropped while this document's moves still exist: joining them keeps
    -- the statement on idx_moves_doc instead of scanning and locking the whole store_stock.
    IF (current_status = 1) THEN
        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> doc_uuid);
    END IF;

    DELETE FROM store_moves WHERE f_doc = doc_uuid;
    DELETE FROM store_stock WHERE f_doc = doc_uuid AND f_qty_in = 0 AND f_qty_left < 0;

    -- 3. Сохраняем/Обновляем заголовок
    INSERT INTO store_document (f_id, f_status, f_doc_type, f_doc_date, f_store_out, f_user_id, f_version, f_data)
    VALUES (doc_uuid, new_status, 2, doc_date, store_id, JSON_VALUE(params, '$.doc_user_id'), 1,
            JSON_EXTRACT(params, '$.doc_data'))
    ON DUPLICATE KEY UPDATE f_status    = VALUES(f_status),
                            f_doc_type  = VALUES(f_doc_type),
                            f_doc_date  = VALUES(f_doc_date),
                            f_store_out = VALUES(f_store_out),
                            f_user_id   = VALUES(f_user_id),
                            f_data      = VALUES(f_data),
                            f_version   = f_version + 1;

    -- 4. Заполняем пользовательские строки
    DELETE FROM store_user WHERE f_doc = doc_uuid;
    INSERT INTO store_user (f_id, f_doc, f_item_id, f_qty, f_comment, f_row)
    SELECT jt.row_uuid, doc_uuid, jt.item_id, jt.qty, jt.comment, jt.row
    FROM JSON_TABLE(params, '$.items[*]'
                    COLUMNS (row_uuid CHAR(36) PATH '$.id', item_id INT PATH '$.item_id',
                        qty DECIMAL(14, 4) PATH '$.qty', comment varchar(255) PATH '$.comment', row int PATH '$.row')
         ) AS jt;

    -- 5. ЦИКЛ СПИСАНИЯ
    IF (new_status = 1) THEN
        SET total_cost = 0;
        SET done = FALSE; -- Сброс перед началом
        OPEN item_cursor;

        item_loop:
        LOOP
            FETCH item_cursor INTO curr_user_item_id, curr_qty_needed, curr_row_id;
            IF done THEN
                LEAVE item_loop;
            END IF;

            SELECT IFNULL(NULLIF(f_storeid, 0), f_id)
            INTO curr_item_id
            FROM c_goods
            WHERE f_id = curr_user_item_id;
            IF (IFNULL(curr_item_id, 0) = 0) THEN
                SET curr_item_id = curr_user_item_id;
            END IF;
            SET done = FALSE;

            fifo_block:
            BEGIN
                DECLARE b_done INT DEFAULT FALSE;
                DECLARE b_id CHAR(36);
                DECLARE b_qty_left DECIMAL(14, 4);
                DECLARE b_price DECIMAL(14, 2);

                DECLARE batch_cursor CURSOR FOR
                    SELECT f_id, f_qty_left, f_price
                    FROM store_stock
                    WHERE f_item_id = curr_item_id
                      AND f_store_id = store_id
                      AND f_qty_left > 0
                    ORDER BY f_batch_date ASC;

                -- Локальный обработчик для FIFO курсора
                DECLARE CONTINUE HANDLER FOR NOT FOUND SET b_done = TRUE;

                OPEN batch_cursor;
                batch_loop:
                LOOP
                    FETCH batch_cursor INTO b_id, b_qty_left, b_price;
                    IF b_done OR curr_qty_needed <= 0 THEN
                        LEAVE batch_loop;
                    END IF;

                    SET take_qty = LEAST(curr_qty_needed, b_qty_left);

                    UPDATE store_stock SET f_qty_left = f_qty_left - take_qty WHERE f_id = b_id;

                    INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_out,
                                             f_price, f_total)
                    VALUES (UUID(), doc_uuid, curr_row_id, b_id, store_id, curr_item_id, take_qty, b_price,
                            take_qty * b_price);

                    SET curr_qty_needed = curr_qty_needed - take_qty;
                    SET total_cost = total_cost + (take_qty * b_price);
                END LOOP;
                CLOSE batch_cursor;
            END fifo_block;

            -- ВАЖНО: сбрасываем основной флаг done, так как b_done мог его триггернуть
            SET done = FALSE;

            -- Обработка минусов
            IF curr_qty_needed > 0 THEN
                SET v_neg_id = UUID();
                SELECT IFNULL(f_lastinputprice, 0) INTO last_input_price FROM c_goods WHERE f_id = curr_item_id;

                INSERT INTO store_stock (f_id, f_doc, f_doc_row_id, f_batch_date, f_store_id, f_item_id, f_qty_in,
                                         f_qty_left, f_price)
                VALUES (v_neg_id, doc_uuid, curr_row_id, doc_date, store_id, curr_item_id, 0, -curr_qty_needed,
                        last_input_price);

                INSERT INTO store_moves (f_id, f_doc, f_doc_row_id, f_batch_id, f_store_id, f_item_id, f_qty_out,
                                         f_price, f_total)
                VALUES (UUID(), doc_uuid, curr_row_id, v_neg_id, store_id, curr_item_id, curr_qty_needed,
                        last_input_price, curr_qty_needed * last_input_price);

                SET total_cost = total_cost + (curr_qty_needed * last_input_price);
            END IF;
        END LOOP;
        CLOSE item_cursor;

        -- Считаем цены для интерфейса
        UPDATE store_user su
            JOIN (SELECT f_doc_row_id, SUM(f_total) AS row_total, SUM(f_qty_out) AS row_qty
                  FROM store_moves
                  WHERE f_doc = doc_uuid
                  GROUP BY f_doc_row_id) AS sm
            ON su.f_id = sm.f_doc_row_id
        SET su.f_price = sm.row_total / NULLIF(sm.row_qty, 0),
            su.f_total = sm.row_total
        WHERE su.f_doc = doc_uuid;
    END IF;

    -- Финальное обновление суммы документа
    UPDATE store_document SET f_sum = total_cost WHERE f_id = doc_uuid;

    RETURN JSON_COMPACT(JSON_OBJECT('status', 0, 'cost', total_cost));
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_remove_input.sql ==========
DROP FUNCTION IF EXISTS sf_store2_input_delete;
DELIMITER $$

CREATE FUNCTION sf_store2_input_delete(p_doc_uuid CHAR(36))
    RETURNS JSON
BEGIN
    DECLARE v_status INT;
    -- Probe without a lock first: FOR UPDATE on a missing PK value takes a gap lock.
    IF NOT EXISTS (SELECT 1 FROM store_document WHERE f_id = p_doc_uuid) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_found');
    END IF;
    SELECT f_status INTO v_status FROM store_document WHERE f_id = p_doc_uuid FOR UPDATE;
    IF v_status IS NULL THEN RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_found'); END IF;

    IF v_status = 1 THEN
        SET sql_safe_updates = 0;

        -- Проверка на реальные продажи (кроме самого прихода)
        IF EXISTS (SELECT 1
                   FROM store_moves sm
                            JOIN store_stock ss ON sm.f_batch_id = ss.f_id
                   WHERE ss.f_doc = p_doc_uuid
                     AND sm.f_doc <> p_doc_uuid) THEN
            RETURN JSON_OBJECT('status', 2, 'msg', 'already_sold_cannot_delete');
        END IF;

        -- Откатываем схлопнутые минусы: снимаем ровно погашенное этим документом,
        -- минус мог быть закрыт частично или несколькими приходами.
        UPDATE store_stock ss
            JOIN (SELECT sm.f_batch_id, SUM(sm.f_qty_in) AS healed
                  FROM store_moves sm
                  WHERE sm.f_doc = p_doc_uuid
                    AND sm.f_qty_in > 0
                    AND sm.f_doc_row_id <> sm.f_batch_id
                  GROUP BY sm.f_batch_id) h ON h.f_batch_id = ss.f_id
        SET ss.f_qty_in     = ss.f_qty_in - h.healed,
            ss.f_qty_left   = ss.f_qty_left - h.healed,
            ss.f_price      = IF(ss.f_qty_in > 0, ss.f_price, 0),
            ss.f_doc        = IF(ss.f_qty_in > 0 AND ss.f_doc <> p_doc_uuid, ss.f_doc, NULL),
            ss.f_doc_row_id = IF(ss.f_doc IS NOT NULL, ss.f_doc_row_id, NULL);

        DELETE FROM store_stock WHERE f_doc = p_doc_uuid;
        DELETE FROM store_moves WHERE f_doc = p_doc_uuid;
    END IF;

    DELETE FROM store_user WHERE f_doc = p_doc_uuid;

    -- Reverse cash-float from purchase payment before deleting ops.
    BEGIN
        DECLARE done_rev INT DEFAULT FALSE;
        DECLARE rev_session_id INT DEFAULT 0;
        DECLARE rev_float_credit DECIMAL(14, 2) DEFAULT 0;
        DECLARE cur_rev CURSOR FOR
            SELECT f_session_id, COALESCE(SUM(f_credit), 0)
            FROM cash_operations
            WHERE f_order_id = p_doc_uuid
              AND f_session_id > 0
              AND f_affects_float = 1
            GROUP BY f_session_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_rev = TRUE;
        OPEN cur_rev;
        rev_loop:
        LOOP
            FETCH cur_rev INTO rev_session_id, rev_float_credit;
            IF done_rev THEN LEAVE rev_loop; END IF;
            UPDATE cash_session
            SET f_amount_expected = f_amount_expected + rev_float_credit
            WHERE f_id = rev_session_id;
        END LOOP;
        CLOSE cur_rev;
    END;

    DELETE FROM cash_operations WHERE f_order_id = p_doc_uuid;
    DELETE FROM cash_debts WHERE f_doc_uuid = p_doc_uuid;
    DELETE FROM b_clients_debts WHERE f_storedoc = p_doc_uuid;
    DELETE FROM store_document WHERE f_id = p_doc_uuid;
    RETURN JSON_OBJECT('status', 0, 'msg', 'ok');
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_remove_output.sql ==========
DROP FUNCTION IF EXISTS sf_store2_output_delete;
DELIMITER $$

CREATE FUNCTION sf_store2_output_delete(p_doc_uuid CHAR(36))
    RETURNS JSON
BEGIN
    DECLARE v_status INT;
    -- Probe without a lock first: FOR UPDATE on a missing PK value takes a gap lock.
    IF NOT EXISTS (SELECT 1 FROM store_document WHERE f_id = p_doc_uuid) THEN
        RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_found');
    END IF;
    SELECT f_status INTO v_status FROM store_document WHERE f_id = p_doc_uuid FOR UPDATE;
    IF v_status IS NULL THEN RETURN JSON_OBJECT('status', 1, 'msg', 'document_not_found'); END IF;

    IF v_status = 1 THEN
        SET sql_safe_updates = 0;

        -- Партия «минус», закрытая приходом: расход аннулируем — не восстанавливаем дыру (-1), а возвращаем
        -- покрытое количество на основную партию прихода (f_batch_id = f_doc_row_id в движении прихода),
        -- иначе остаётся 19 + (-1) = 18 вместо 20.
        UPDATE store_moves sm_main
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sm_main.f_batch_id = x.rid AND sm_main.f_doc_row_id = x.rid
        SET sm_main.f_qty_in = sm_main.f_qty_in + x.qmerge,
            sm_main.f_total  = (sm_main.f_qty_in + x.qmerge) * sm_main.f_price;

        UPDATE store_stock sr
            INNER JOIN (SELECT b.rid, SUM(b.qmerge) AS qmerge
                        FROM (SELECT am.f_doc_row_id                                     AS rid,
                                     LEAST(o.qty_out, ss.f_qty_in, am.abs_q)             AS qmerge
                              FROM store_stock ss
                                  JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                        FROM store_moves
                                        WHERE f_doc = p_doc_uuid
                                        GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                                  JOIN (SELECT DISTINCT sm_in.f_batch_id
                                        FROM store_moves sm_in
                                        WHERE sm_in.f_qty_in > 0
                                          AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                                  JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                        FROM store_moves
                                        WHERE f_qty_in > 0
                                          AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                        GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                              WHERE ss.f_qty_left = 0
                                AND ss.f_qty_in > 0) b
                        GROUP BY b.rid) x ON sr.f_id = x.rid
        SET sr.f_qty_in = sr.f_qty_in + x.qmerge,
            sr.f_qty_left = sr.f_qty_left + x.qmerge;

        UPDATE store_stock ss
            INNER JOIN (SELECT am.f_batch_id                                       AS nid,
                               SUM(LEAST(o.qty_out, ss.f_qty_in, am.abs_q))          AS qmerge
                        FROM store_stock ss
                            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                                  FROM store_moves
                                  WHERE f_doc = p_doc_uuid
                                  GROUP BY f_batch_id) o ON o.f_batch_id = ss.f_id
                            JOIN (SELECT DISTINCT sm_in.f_batch_id
                                  FROM store_moves sm_in
                                  WHERE sm_in.f_qty_in > 0
                                    AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
                            JOIN (SELECT f_batch_id, f_doc_row_id, SUM(f_qty_in) AS abs_q
                                  FROM store_moves
                                  WHERE f_qty_in > 0
                                    AND f_doc_row_id <> f_batch_id
                                          AND f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)
                                  GROUP BY f_batch_id, f_doc_row_id) am ON am.f_batch_id = ss.f_id
                        WHERE ss.f_qty_left = 0
                          AND ss.f_qty_in > 0
                        GROUP BY am.f_batch_id) d ON ss.f_id = d.nid
        SET ss.f_qty_in = ss.f_qty_in - d.qmerge,
            ss.f_qty_left = 0;

        -- Обычные партии (без погашения минуса приходом): вернуть списанное в f_qty_left.
        -- Делать до DELETE погашений, иначе hx пустой и к партии «минус» снова прибавится qty_out.
        UPDATE store_stock ss
            JOIN (SELECT f_batch_id, SUM(f_qty_out) AS qty_out
                  FROM store_moves
                  WHERE f_doc = p_doc_uuid
                  GROUP BY f_batch_id) sm ON sm.f_batch_id = ss.f_id
            LEFT JOIN (SELECT DISTINCT sm_in.f_batch_id
                       FROM store_moves sm_in
                       WHERE sm_in.f_qty_in > 0
                         AND sm_in.f_doc_row_id <> sm_in.f_batch_id
                                          AND sm_in.f_batch_id IN (SELECT dm.f_batch_id FROM store_moves dm WHERE dm.f_doc = p_doc_uuid)) hx ON hx.f_batch_id = ss.f_id
        SET ss.f_qty_left = ss.f_qty_left + sm.qty_out
        WHERE hx.f_batch_id IS NULL;

        DELETE sm_abs
        FROM store_moves sm_abs
            INNER JOIN (SELECT DISTINCT f_batch_id AS bid
                        FROM store_moves
                        WHERE f_doc = p_doc_uuid) om ON om.bid = sm_abs.f_batch_id
        WHERE sm_abs.f_qty_in > 0
          AND sm_abs.f_doc_row_id <> sm_abs.f_batch_id;

        -- Удаление минусов (только если они не привязаны к живому Приходу)
        DELETE ss
        FROM store_stock ss
        WHERE ss.f_doc = p_doc_uuid
          AND ss.f_qty_in = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves WHERE f_batch_id = ss.f_id AND f_doc <> p_doc_uuid);

        DELETE ss
        FROM store_stock ss
            JOIN (SELECT DISTINCT f_batch_id AS bid FROM store_moves WHERE f_doc = p_doc_uuid) b ON b.bid = ss.f_id
        WHERE ss.f_qty_in = 0
          AND ss.f_qty_left = 0
          AND NOT EXISTS (SELECT 1 FROM store_moves sm WHERE sm.f_batch_id = ss.f_id AND sm.f_doc <> p_doc_uuid);

        DELETE FROM store_moves WHERE f_doc = p_doc_uuid;
    END IF;

    DELETE FROM store_user WHERE f_doc = p_doc_uuid;
    DELETE FROM store_document WHERE f_id = p_doc_uuid;
    RETURN JSON_OBJECT('status', 0, 'msg', 'ok');
END$$
DELIMITER ;
DELIMITER ;

-- ========== store2_remove_root.sql ==========
DROP FUNCTION IF EXISTS sf_store2_doc_delete;
DELIMITER $$

CREATE FUNCTION sf_store2_doc_delete(p_doc_uuid CHAR(36))
    RETURNS longtext
BEGIN
    DECLARE v_doc_type INT;
    DECLARE v_res longtext;

    SELECT f_doc_type
    INTO v_doc_type
    FROM store_document
    WHERE f_id = p_doc_uuid FOR UPDATE;

    IF v_doc_type IS NULL THEN
        RETURN JSON_COMPACT(JSON_OBJECT('status', 1, 'msg', 'document_not_found'));
    END IF;

    CASE v_doc_type
        WHEN 1 THEN SET v_res = sf_store2_input_delete(p_doc_uuid);
        WHEN 2 THEN SET v_res = sf_store2_output_delete(p_doc_uuid);
        WHEN 3 THEN SET v_res = sf_store2_move_delete(p_doc_uuid);
        WHEN 4 THEN SET v_res = sf_store2_complect_delete(p_doc_uuid);
        ELSE
            RETURN JSON_COMPACT(JSON_OBJECT('status', 3, 'msg', 'unknown_doc_type', 'doc_type', v_doc_type));
    END CASE;

    RETURN v_res;
END$$
DELIMITER ;
DELIMITER ;

-- ========== store_create_doc.sql ==========
delimiter $$
DROP PROCEDURE if EXISTS sf_create_store_document$$
CREATE
    DEFINER = `root`@`localhost` PROCEDURE `sf_create_store_document`(
    IN `params` JSON)
    LANGUAGE SQL
    NOT DETERMINISTIC
    CONTAINS SQL
    SQL SECURITY DEFINER
    COMMENT ''
sp:
BEGIN
    -- 26/01/2026
-- data
    DECLARE aheaderid CHAR(36) CHARACTER SET LATIN1 COLLATE latin1_general_ci;
    declare goods_disassembly json;
    DECLARE
        EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            RESIGNAL;
        END;

    SET @timestartd = CURRENT_TIMESTAMP();

    select JSON_EXTRACT(params, '$.header') INTO @header;
    SELECT JSON_VALUE(@header, '$.f_id') INTO aheaderid;
    SELECT json_extract(params, '$.body') INTO @header_body;
    SELECT JSON_EXTRACT(params, '$.goods') INTO @goods;
    select json_extract(params, '$.goods_disassembly') into goods_disassembly;
    SELECT JSON_EXTRACT(params, '$.add') INTO @additional;
    SELECT JSON_EXTRACT(params, '$.partner') INTO @partner;

    if (aheaderid is null or LENGTH(aheaderid) = 0) then
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'HEADER ID IS EMPTY';
    END if;

-- delete old document
    SELECT f_id, f_state, f_payment
    INTO @tid, @tstate, @payment
    FROM a_header
    WHERE f_id = aheaderid;
-- check if make doc draft and other documunt depended on  this doc
    if (@tid IS NOT NULL AND @tstate = 1 AND JSON_VALUE(@header, '$.f_state') = 2) then
        SELECT GROUP_CONCAT(DISTINCT (d.f_userid), ' ', d.f_date SEPARATOR '\n')
        INTO @tcheck
        from a_store s
                 inner join a_header d on d.f_id = s.f_document
        where f_basedoc = aheaderid
          and f_document <> aheaderid
          and s.f_type = -1;
        if
            (@tcheck IS NOT NULL) then
            INSERT INTO a_result(f_session, f_document, f_timestamp, f_done, f_elapsed, f_request, f_result)
            VALUES (JSON_VALUE(params, '$.session'), JSON_VALUE(@header, '$.f_id'), @timestartd, @timeendd,
                    TIMESTAMPDIFF(SECOND, @timestartd, @timeendd), params,
                    JSON_OBJECT('status', 0, 'message', CONCAT_WS('\n', 'Փասթաթուղթը կախված է', @tcheck)));
            leave
                sp;
        END if;
    END if;


    if (JSON_VALUE(params, '$.notransaction') IS NULL) then
        START TRANSACTION;
    END if;

    if (@tid IS NOT NULL) then
        DELETE from a_store_valid where f_document = aheaderid;
        DELETE FROM a_store WHERE f_document = aheaderid;
        DELETE FROM a_store_draft WHERE f_document = aheaderid;
        DELETE FROM a_header WHERE f_id = aheaderid;
        DELETE FROM a_header_store WHERE f_id = aheaderid;
        DELETE FROM b_clients_debts WHERE f_storedoc = aheaderid;
        delete from a_complectation_additions where f_header = aheaderid;
        if (@payment IS NOT NULL) then
            SELECT sf_remove_cashdoc(@payment)
            INTO @tmp;
        END if;
    END if;
    SET @message = '';
    SET @STATUS = 1;


-- gen document id
    SET @userid = JSON_VALUE(@header, '$.f_userid');
    if (@userid IS NULL OR @userid = 0) then
        case (JSON_VALUE(@header, '$.f_type'))
            when 1 then begin
                select coalesce(f_inputcounter, 0) + 1
                INTO @userid
                from c_storages
                where f_id = jsON_VALUE(@header, '$.f_storein');
                UPDATE c_storages SET f_inputcounter=@userid WHERE f_id = jsON_VALUE(@header, '$.f_storein');
            END;
            when 2 then begin
                select coalesce(f_outcounter, 0) + 1
                INTO @userid
                from c_storages
                where f_id = JSON_VALUE(@header, '$.f_storeout');
                UPDATE c_storages
                SET f_outcounter=@userid
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            when 3 then begin
                select coalesce(f_movecounter, 0) + 1
                INTO @userid
                from c_storages
                where f_id = jsON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_movecounter=@userid
                WHERE f_id = jsON_VALUE(@header, '$.f_storein');
            END;
            when 6 then begin
                select coalesce(f_complectcounter, 0) + 1
                INTO @userid
                from c_storages
                where f_id = jsON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_complectcounter=@userid
                WHERE f_id = jsON_VALUE(@header, '$.f_storein');
            END;
            when 8 then begin
                select coalesce(f_complectcounter, 0) + 1
                INTO @userid
                from c_storages
                where f_id = jsON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_complectcounter=@userid
                WHERE f_id = jsON_VALUE(@header, '$.f_storein');
            end;
            END case;
    END if;

-- header
    INSERT INTO a_header (f_id, f_userid, f_state, f_type,
                          f_operator, f_date, f_createdate, f_createtime,
                          f_partner, f_amount, f_comment, f_payment, f_paid, f_currency, f_working_session, f_body)
    VALUES (JSON_VALUE(@header, '$.f_id'), @userid, JSON_VALUE(@header, '$.f_state'), JSON_VALUE(@header, '$.f_type'),
            JSON_VALUE(@header, '$.f_operator'), JSON_VALUE(@header, '$.f_date'), CURRENT_DATE(), CURRENT_TIME(),
            JSON_VALUE(@header, '$.f_partner'), JSON_VALUE(@header, '$.f_amount'), JSON_VALUE(@header, '$.f_comment'),
            JSON_VALUE(@header, '$.f_payment'),
            JSON_VALUE(@header, '$.f_paid'), JSON_VALUE(@header, '$.f_currency'),
            JSON_VALUE(@header, '$.f_working_session'), JSON_DETAILED(@header_body));

    INSERT INTO a_header_store (f_id, f_reason, f_storein, f_storeout, f_invoice, f_saleuuid, f_body, f_baseonsale,
                                f_complectation, f_complectationqty)
    VALUES (aheaderid, JSON_VALUE(@header_body, '$.f_reason'), jsON_VALUE(@header, '$.f_storein'),
            jsON_VALUE(@header, '$.f_storeout'), JSON_VALUE(params, '$.body.f_invoice'),
            JSON_VALUE(@header_body, '$.f_saleuuid'), params, coalesce(JSON_VALUE(@header_body, '$.f_basedonsale'), 0),
            JSON_VALUE(@header_body, '$.f_complectationcode'), JSON_VALUE(@header_body, '$.f_complectationqty'));

    SET @iadd = 0;
    while (@iadd < JSON_LENGTH(@additional))
        DO
            SELECT JSON_extract(@additional, CONCAT('$[', @iadd, ']'))
            INTO @a;
            INSERT INTO a_complectation_additions (f_id, f_header, f_name, f_amount, f_row)
            VALUES (UUID(), aheaderid, JSON_VALUE(@a, '$.f_name'), JSON_VALUE(@a, '$.f_amount'),
                    JSON_VALUE(@a, '$.f_row'));
            SET
                @iadd = @iadd + 1;
        END while;
    if (@iadd > 0) then
        UPDATE s_draft
        SET f_value=aheaderid
        WHERE f_name = 'last_store_additions';
    END if;


-- a_store_draft input
    case (JSON_VALUE(@header, '$.f_type'))
        WHEN 1 THEN BEGIN
            select JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', 1, 'store', JSON_VALUE(@header, '$.f_storein'),
                               'state', JSON_VALUE(@header, '$.f_state'), 'partner', JSON_VALUE(@header, '$.f_partner'))
            INTO @goods;
            call sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET @STATUS = JSON_VALUE(@result, '$.status');
            SET @message = JSON_VALUE(@result, '$.message');
        END;
        WHEN 2 THEN BEGIN
            select JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'))
            INTO @goods;
            call sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET @STATUS = JSON_VALUE(@result, '$.status');
            SET @message = JSON_VALUE(@result, '$.message');
        END;
        WHEN 3 THEN BEGIN
            select JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'),
                               'move', 1, 'storein', JSON_VALUE(@header, '$.f_storein'))
            INTO @goods;
            call sf_create_store_goods(@goods);
            SELECT @create_store_goods
            into @result;
            SET @STATUS = JSON_VALUE(@result, '$.status');
            SET @message = JSON_VALUE(@result, '$.message');
        END;
        when 6 then begin
            select JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'))
            INTO @goods;
            call sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET @STATUS = JSON_VALUE(@result, '$.status');
            SET @message = JSON_VALUE(@result, '$.message');
            if (@STATUS = 1) then
                SELECT JSON_EXTRACT(params, '$.complect')
                INTO @comp;
                SELECT SUM(f_qty * f_price)
                INTO @compprice
                FROM a_store_draft
                WHERE f_document = aheaderid;
                SELECT (coalesce(SUM(f_amount), 0) + @compprice) / JSON_VALUE(@comp, '$.f_qty')
                INTO @compprice
                FROM a_complectation_additions
                WHERE f_header = aheaderid;
                SELECT JSON_OBJECT('f_goods', JSON_VALUE(@comp, '$.f_goods'), 'f_qty', JSON_VALUE(@comp, '$.f_qty'),
                                   'f_price',
                                   @compprice,
                                   'state', JSON_VALUE(@header, '$.f_state'))
                INTO @goods_complect_g;
                select JSON_OBJECT('goods', json_array(JSON_DETAILED(@goods_complect_g)), 'ftype', 1, 'store',
                                   JSON_VALUE(@header, '$.f_storein'), 'state', JSON_VALUE(@header, '$.f_state'))
                INTO @goods_complect;
                call sf_create_store_goods(@goods_complect);
            END if;
        END;
        -- DISASSEMBLY
        when 8 then begin
            select JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'))
            INTO @goods;
            call sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET @STATUS = JSON_VALUE(@result, '$.status');
            SET @message = JSON_VALUE(@result, '$.message');
            if (@status = 1) then
                select JSON_OBJECT('goods', JSON_DETAILED(goods_disassembly), 'ftype', 1, 'store',
                                   JSON_VALUE(@header, '$.f_storein'), 'state',
                                   JSON_VALUE(@header, '$.f_state'))
                INTO @goods;
                call sf_create_store_goods(@goods);
                SELECT @create_store_goods
                INTO @result;
                SET @STATUS = JSON_VALUE(@result, '$.status');
                SET @message = JSON_VALUE(@result, '$.message');
            end if;
        end;
        ELSE BEGIN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'UNKNOWN DOCUMENT TYPE';
        END;
        END CASE;


    -- partner and paymnent
-- first, payment
    if (JSON_VALUE(@partner, '$.paid') = 1 AND JSON_VALUE(@header, '$.f_state') = 1) then
        SELECT JSON_OBJECT('f_cashout', JSON_VALUE(@partner, '$.cash'), 'f_currency',
                           JSON_VALUE(@header, '$.f_currency'),
                           'f_amount', JSON_VALUE(@header, '$.f_amount'), 'f_purpose',
                           CONCAT('Պահեստի մուտքի վճարում ', @userid), 'f_comment',
                           CONCAT('Պահեստի մուտքի վճարում ', @userid),
                           'f_operator', JSON_VALUE(@header, '$.f_operator'), 'f_date', JSON_VALUE(@header, '$.f_date'))
        INTO @cashdoc;
        SELECT sf_create_cashdoc(@cashdoc)
        INTO @cashdocresult;
        UPDATE a_header
        SET f_payment=JSON_VALUE(@cashdocresult, '$.cashdoc')
        WHERE f_id = aheaderid;
    END if;
-- debts    , ets...
    if ((CAST(@STATUS AS unsigned) = 1) AND (JSON_VALUE(@header, '$.f_state') = 1) AND
        JSON_VALUE(@header, '$.f_nodebtop') IS null) then
        if (JSON_VALUE(@partner, '$.partner') > 0) then
            SELECT f_hall
            INTO @thall
            FROM c_storages
            WHERE f_id = JSON_VALUE(@header, '$.f_storein')
               OR f_id = JSON_VALUE(@header, '$.f_storeout');
            case JSON_VALUE(@header, '$.f_type')
                When 1 then BEGIN
                    # decrease debt if goods return from partner

                    if (JSON_VALUE(@header, '$.f_reason') = 11) then
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'),
                                JSON_VALUE(@header, '$.f_amount'),
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 1, @thall);
                    END if;
                    #debt
                    if (JSON_VALUE(@partner, '$.paid') = 0 AND JSON_VALUE(@header, '$.f_reason') <> 11) then
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'),
                                JSON_VALUE(@header, '$.f_amount') * -1,
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 2, @thall);
                    END if;
                END;
                when 2 then BEGIN
                    if (JSON_VALUE(@header, '$.f_reason') = 9) then
                        SELECT SUM(f_qty * f_price)
                        INTO @ttotal
                        FROM a_store
                        WHERE f_id = aheaderid;
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'), @ttotal,
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 2, @thall);
                    END if;
                END;
                ELSE BEGIN
                END;
                END case;
        END if;
        case JSON_VALUE(@header, '$.f_type')
            WHEn 1 then begin
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
            end;
            when 2 then begin
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            end;
            when 3 then begin
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            when 6 then begin
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            when 8 then begin
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            END case;
    END if;

    if (CAST(@STATUS AS unsigned) = 1) then
        UPDATE a_store
        SET f_total=f_qty * f_price
        WHERE f_document = aheaderid;
        UPDATE a_store_draft
        SET f_total=f_qty * f_price
        WHERE f_document = aheaderid;
        case JSON_VALUE(@header, '$.f_type')
            when 1 then UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total) FROM a_store_draft WHERE f_document = aheaderid)
                        WHERE f_id = aheaderid;
            when 2 then UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total) FROM a_store_draft WHERE f_document = aheaderid)
                        WHERE f_id = aheaderid;
            when 3 then UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total)
                                      FROM a_store_draft
                                      WHERE f_document = aheaderid
                                        AND f_type = -1)
                        WHERE f_id = aheaderid;
            when 6 then UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total)
                                      FROM a_store_draft
                                      WHERE f_document = aheaderid
                                        AND f_type = -1)
                        WHERE f_id = aheaderid;
            END case;
        if (JSON_LENGTH(@additional) > 0) then
            UPDATE a_header
            SET f_amount=f_amount +
                         (SELECT COALESCE(SUM(f_amount), 0) FROM a_complectation_additions WHERE f_header = aheaderid)
            WHERE f_id = aheaderid;
        END if;
        if (JSON_VALUE(params, '$.notransaction') IS NULL) then
            COMMIT;
        END if;
    ELSE
        if (JSON_VALUE(params, '$.notransaction') IS NULL) then
            ROLLBACK;
        END if;
    END if;

    SET @timeendd = CURRENT_TIMESTAMP;
    INSERT INTO a_result(f_session, f_document, f_timestamp, f_done, f_elapsed, f_request, f_result)
    VALUES (JSON_VALUE(params, '$.session'), JSON_VALUE(@header, '$.f_id'), @timestartd, @timeendd,
            TIMESTAMPDIFF(SECOND, @timestartd, @timeendd), params,
            JSON_OBJECT('status', CAST(@STATUS AS unsigned), 'message', @message, 'state',
                        cast(JSON_VALUE(@header, '$.f_state') AS unsigned)));
END$$

delimiter ;
DELIMITER ;

-- ========== store_create_document.sql ==========
DROP PROCEDURE IF EXISTS sf_create_store_document;
DELIMITER $$
CREATE
    DEFINER = `root`@`localhost` PROCEDURE `sf_create_store_document`(
    IN `params` JSON
)
    LANGUAGE SQL
    NOT DETERMINISTIC
    CONTAINS SQL
    SQL SECURITY DEFINER
    COMMENT ''
sp:
BEGIN
    DECLARE
        aheaderid CHAR(36) CHARACTER SET latin1 COLLATE latin1_general_ci;
    DECLARE
        EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            RESIGNAL;
        END;

    SET
        @timestartd = CURRENT_TIMESTAMP();
    -- 26/02/2026 31.03.2025
-- data
    SELECT JSON_EXTRACT(params, '$.header') INTO @header;
    SELECT JSON_VALUE(@header, '$.f_id') INTO aheaderid;
    SELECT JSON_EXTRACT(params, '$.body') INTO @header_body;
    SELECT JSON_EXTRACT(params, '$.goods') INTO @goods;
    SELECT JSON_EXTRACT(params, '$.goods_decomplectation') INTO @goods_decomplectation;
    SELECT JSON_EXTRACT(params, '$.add') INTO @additional;
    SELECT JSON_EXTRACT(params, '$.partner') INTO @partner;

    IF (aheaderid IS NULL OR LENGTH(aheaderid) = 0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'HEADER ID IS EMPTY';
    END IF;

-- delete old document
    SELECT f_id, f_state, f_payment
    INTO @tid, @tstate, @payment
    FROM a_header
    WHERE f_id = aheaderid;
-- check if make doc draft and other documunt depended on  this doc
    IF (@tid IS NOT NULL AND @tstate = 1 AND JSON_VALUE(@header, '$.f_state') = 2) THEN
        SELECT GROUP_CONCAT(DISTINCT (d.f_userid), ' ', d.f_date SEPARATOR '\n')
        INTO @tcheck
        FROM a_store s
                 INNER JOIN a_header d ON d.f_id = s.f_document
        WHERE f_basedoc = aheaderid
          AND f_document <> aheaderid
          AND s.f_type = -1;
        IF
            (@tcheck IS NOT NULL) THEN
            INSERT INTO a_result(f_session, f_document, f_timestamp, f_done, f_elapsed, f_request, f_result)
            VALUES (JSON_VALUE(params, '$.session'), JSON_VALUE(@header, '$.f_id'), @timestartd, @timeendd,
                    TIMESTAMPDIFF(SECOND, @timestartd, @timeendd), params,
                    JSON_OBJECT('status', 0, 'message', CONCAT_WS('\n', 'Փասթաթուղթը կախված է', @tcheck)));
            LEAVE
                sp;
        END IF;
    END IF;


    IF (JSON_VALUE(params, '$.notransaction') IS NULL) THEN
        START TRANSACTION;
    END IF;

    IF (@tid IS NOT NULL) THEN
        DELETE FROM a_store_valid WHERE f_document = aheaderid;
        DELETE FROM a_store WHERE f_document = aheaderid;
        DELETE FROM a_store_draft WHERE f_document = aheaderid;
        DELETE
        FROM a_header
        WHERE f_id = aheaderid;
        DELETE
        FROM a_header_store
        WHERE f_id = aheaderid;
        DELETE
        FROM b_clients_debts
        WHERE f_storedoc = aheaderid;
        DELETE
        FROM a_complectation_additions
        WHERE f_header = aheaderid;
        IF (@payment IS NOT NULL) THEN
            SELECT sf_remove_cashdoc(@payment)
            INTO @tmp;
        END IF;
    END IF;
    SET
        @message = '';
    SET
        @status = 1;


-- gen document id
    SET @userid = JSON_VALUE(@header, '$.f_userid');
    IF
        (@userid IS NULL OR @userid = 0) THEN
        CASE (JSON_VALUE(@header, '$.f_type'))
            WHEN 1 THEN BEGIN
                SELECT COALESCE(f_inputcounter, 0) + 1
                INTO @userid
                FROM c_storages
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_inputcounter=@userid
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
            END;
            WHEN 2 THEN BEGIN
                SELECT COALESCE(f_outcounter, 0) + 1
                INTO @userid
                FROM c_storages
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
                UPDATE c_storages
                SET f_outcounter=@userid
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            WHEN 3 THEN BEGIN
                SELECT COALESCE(f_movecounter, 0) + 1
                INTO @userid
                FROM c_storages
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_movecounter=@userid
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
            END;
            WHEN 6 THEN BEGIN
                SELECT COALESCE(f_complectcounter, 0) + 1
                INTO @userid
                FROM c_storages
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_complectcounter=@userid
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
            END;
            END CASE;
    END IF;

#header
    INSERT INTO a_header (f_id, f_userid, f_state, f_type,
                          f_operator, f_date, f_createdate, f_createtime,
                          f_partner, f_amount, f_comment, f_payment, f_paid, f_currency, f_working_session, f_body)
    VALUES (JSON_VALUE(@header, '$.f_id'), @userid, JSON_VALUE(@header, '$.f_state'), JSON_VALUE(@header, '$.f_type'),
            JSON_VALUE(@header, '$.f_operator'), JSON_VALUE(@header, '$.f_date'), CURRENT_DATE(), CURRENT_TIME(),
            JSON_VALUE(@header, '$.f_partner'), JSON_VALUE(@header, '$.f_amount'), JSON_VALUE(@header, '$.f_comment'),
            JSON_VALUE(@header, '$.f_payment'),
            JSON_VALUE(@header, '$.f_paid'), JSON_VALUE(@header, '$.f_currency'),
            JSON_VALUE(@header, '$.f_working_session'), JSON_DETAILED(@header_body));

    INSERT INTO a_header_store (f_id, f_reason, f_storein, f_storeout, f_invoice, f_saleuuid, f_body, f_baseonsale,
                                f_complectation, f_complectationqty)
    VALUES (aheaderid, JSON_VALUE(@header_body, '$.f_reason'), JSON_VALUE(@header, '$.f_storein'),
            JSON_VALUE(@header, '$.f_storeout'), JSON_VALUE(params, '$.body.f_invoice'),
            JSON_VALUE(@header_body, '$.f_saleuuid'), params, COALESCE(JSON_VALUE(@header_body, '$.f_basedonsale'), 0),
            JSON_VALUE(@header_body, '$.f_complectationcode'), JSON_VALUE(@header_body, '$.f_complectationqty'));

    SET
        @iadd = 0;
    WHILE (@iadd < JSON_LENGTH(@additional))
        DO
            SELECT JSON_EXTRACT(@additional, CONCAT('$[', @iadd, ']'))
            INTO @a;
            INSERT INTO a_complectation_additions (f_id, f_header, f_name, f_amount, f_row)
            VALUES (UUID(), aheaderid, JSON_VALUE(@a, '$.f_name'), JSON_VALUE(@a, '$.f_amount'),
                    JSON_VALUE(@a, '$.f_row'));
            SET
                @iadd = @iadd + 1;
        END WHILE;
    IF
        (@iadd > 0) THEN
        UPDATE s_draft
        SET f_value=aheaderid
        WHERE f_name = 'last_store_additions';
    END IF;


-- a_store_draft input
    CASE (JSON_VALUE(@header, '$.f_type'))
        WHEN 1 THEN BEGIN
            SELECT JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', 1, 'store', JSON_VALUE(@header, '$.f_storein'),
                               'state', JSON_VALUE(@header, '$.f_state'), 'partner', JSON_VALUE(@header, '$.f_partner'))
            INTO @goods;
            CALL sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET
                @status = JSON_VALUE(@result, '$.status');
            SET
                @message = JSON_VALUE(@result, '$.message');
        END;
        WHEN 2 THEN BEGIN
            SELECT JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'))
            INTO @goods;
            CALL sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET
                @status = JSON_VALUE(@result, '$.status');
            SET
                @message = JSON_VALUE(@result, '$.message');
        END;
        WHEN 3 THEN BEGIN
            SELECT JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'),
                               'move', 1, 'storein', JSON_VALUE(@header, '$.f_storein'))
            INTO @goods;
            CALL sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET
                @status = JSON_VALUE(@result, '$.status');
            SET
                @message = JSON_VALUE(@result, '$.message');
        END;
        WHEN 6 THEN BEGIN
            SELECT JSON_OBJECT('goods', JSON_DETAILED(@goods), 'ftype', -1, 'store',
                               JSON_VALUE(@header, '$.f_storeout'), 'state',
                               JSON_VALUE(@header, '$.f_state'))
            INTO @goods;
            CALL sf_create_store_goods(@goods);
            SELECT @create_store_goods
            INTO @result;
            SET
                @status = JSON_VALUE(@result, '$.status');
            SET
                @message = JSON_VALUE(@result, '$.message');
            IF
                (@status = 1) THEN
                SELECT JSON_EXTRACT(params, '$.complect')
                INTO @comp;
                SELECT SUM(f_qty * f_price)
                INTO @compprice
                FROM a_store_draft
                WHERE f_document = aheaderid;
                SELECT (COALESCE(SUM(f_amount), 0) + @compprice) / JSON_VALUE(@comp, '$.f_qty')
                INTO @compprice
                FROM a_complectation_additions
                WHERE f_header = aheaderid;
                SELECT JSON_OBJECT('f_goods', JSON_VALUE(@comp, '$.f_goods'), 'f_qty', JSON_VALUE(@comp, '$.f_qty'),
                                   'f_price',
                                   @compprice,
                                   'state', JSON_VALUE(@header, '$.f_state'))
                INTO @goods_complect_g;
                SELECT JSON_OBJECT('goods', JSON_ARRAY(JSON_DETAILED(@goods_complect_g)), 'ftype', 1, 'store',
                                   JSON_VALUE(@header, '$.f_storein'), 'state', JSON_VALUE(@header, '$.f_state'))
                INTO @goods_complect;
                CALL sf_create_store_goods(@goods_complect);
            END IF;
        END;
        ELSE BEGIN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'UNKNOWN DOCUMENT TYPE';
        END;
        END CASE;


    -- partner and paymnent
-- first, payment
    IF (JSON_VALUE(@partner, '$.paid') = 1 AND JSON_VALUE(@header, '$.f_state') = 1) THEN
        SELECT JSON_OBJECT('f_cashout', JSON_VALUE(@partner, '$.cash'), 'f_currency',
                           JSON_VALUE(@header, '$.f_currency'),
                           'f_amount', JSON_VALUE(@header, '$.f_amount'), 'f_purpose',
                           CONCAT('Պահեստի մուտքի վճարում ', @userid), 'f_comment',
                           CONCAT('Պահեստի մուտքի վճարում ', @userid),
                           'f_operator', JSON_VALUE(@header, '$.f_operator'), 'f_date', JSON_VALUE(@header, '$.f_date'))
        INTO @cashdoc;
        SELECT sf_create_cashdoc(@cashdoc)
        INTO @cashdocresult;
        UPDATE a_header
        SET f_payment=JSON_VALUE(@cashdocresult, '$.cashdoc')
        WHERE f_id = aheaderid;
    END IF;
-- debts    , ets...
    IF ((CAST(@status AS unsigned) = 1) AND (JSON_VALUE(@header, '$.f_state') = 1) AND
        JSON_VALUE(@header, '$.f_nodebtop') IS NULL) THEN
        IF (JSON_VALUE(@partner, '$.partner') > 0) THEN
            SELECT f_hall
            INTO @thall
            FROM c_storages
            WHERE f_id = JSON_VALUE(@header, '$.f_storein')
               OR f_id = JSON_VALUE(@header, '$.f_storeout');
            CASE JSON_VALUE(@header, '$.f_type')
                WHEN 1 THEN BEGIN
                    # decrease debt if goods return from partner

                    IF (JSON_VALUE(@header, '$.f_reason') = 9) THEN
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'),
                                JSON_VALUE(@header, '$.f_amount'),
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 1, @thall);
                    END IF;
                    #debt
                    IF (JSON_VALUE(@partner, '$.paid') = 0 AND JSON_VALUE(@header, '$.f_reason') <> 11) THEN
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'),
                                JSON_VALUE(@header, '$.f_amount') * -1,
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 2, @thall);
                    END IF;
                END;
                WHEN 2 THEN BEGIN
                    IF (JSON_VALUE(@header, '$.f_reason') = 9) THEN
                        SELECT f_amount
                        INTO @ttotal
                        FROM a_header
                        WHERE f_id = aheaderid;
                        INSERT INTO b_clients_debts (f_date, f_costumer, f_amount, f_storedoc, f_currency, f_source,
                                                     f_flag)
                        VALUES (JSON_VALUE(@header, '$.f_date'), JSON_VALUE(@partner, '$.partner'), @ttotal,
                                aheaderid, JSON_VALUE(@header, '$.f_currency'), 2, @thall);
                    END IF;
                END;
                ELSE BEGIN
                END;
                END CASE;
        END IF;
        CASE JSON_VALUE(@header, '$.f_type')
            WHEN 1 THEN UPDATE c_storages
                        SET f_have_changes=1
                        WHERE f_id = JSON_VALUE(@header, '$.f_storein');
            WHEN 2 THEN UPDATE c_storages
                        SET f_have_changes=1
                        WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            WHEN 3 THEN BEGIN
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            WHEN 6 THEN BEGIN
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storein');
                UPDATE c_storages
                SET f_have_changes=1
                WHERE f_id = JSON_VALUE(@header, '$.f_storeout');
            END;
            END CASE;
    END IF;

    IF (CAST(@status AS unsigned) = 1) THEN

        UPDATE a_store
        SET f_total=f_qty * f_price
        WHERE f_document = aheaderid;
        UPDATE a_store_draft
        SET f_total=f_qty * f_price
        WHERE f_document = aheaderid;
        CASE JSON_VALUE(@header, '$.f_type')
            WHEN 1 THEN UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total) FROM a_store_draft WHERE f_document = aheaderid)
                        WHERE f_id = aheaderid;
            WHEN 2 THEN UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total) FROM a_store_draft WHERE f_document = aheaderid)
                        WHERE f_id = aheaderid;
            WHEN 3 THEN UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total)
                                      FROM a_store_draft
                                      WHERE f_document = aheaderid
                                        AND f_type = -1)
                        WHERE f_id = aheaderid;
            WHEN 6 THEN UPDATE a_header
                        SET f_amount=(SELECT SUM(f_total)
                                      FROM a_store_draft
                                      WHERE f_document = aheaderid
                                        AND f_type = -1)
                        WHERE f_id = aheaderid;
            END CASE;
        IF
            (JSON_LENGTH(@additional) > 0) THEN
            UPDATE a_header
            SET f_amount=f_amount +
                         (SELECT COALESCE(SUM(f_amount), 0) FROM a_complectation_additions WHERE f_header = aheaderid)
            WHERE f_id = aheaderid;
        END IF;
        IF
            (JSON_VALUE(params, '$.notransaction') IS NULL) THEN
            COMMIT;
        END IF;
    ELSE
        IF (JSON_VALUE(params, '$.notransaction') IS NULL) THEN
            ROLLBACK;
        END IF;
    END IF;

    SET
        @timeendd = CURRENT_TIMESTAMP;
    INSERT INTO a_result(f_session, f_document, f_timestamp, f_done, f_elapsed, f_request, f_result)
    VALUES (JSON_VALUE(params, '$.session'), JSON_VALUE(@header, '$.f_id'), @timestartd, @timeendd,
            TIMESTAMPDIFF(SECOND, @timestartd, @timeendd), params,
            JSON_OBJECT('status', CAST(@status AS unsigned), 'message', @message, 'state',
                        CAST(JSON_VALUE(@header, '$.f_state') AS unsigned)));
END$$

DELIMITER ;
DELIMITER ;

-- ========== store_create_goods.sql ==========
delimiter $$

DROP FUNCTION if EXISTS sf_create_store_goods$$
DROP PROCEDURE if EXISTS sf_create_store_goods$$
CREATE procedure sf_create_store_goods(params JSON)
sf_create_store_goods:BEGIN
-- 16/10/24 10:12
DECLARE storerec CHAR(36) CHARACTER SET LATIN1 COLLATE LATIN1_GENERAL_CI;
SET @ftype = JSON_VALUE(params, '$.ftype');
SET @store = JSON_VALUE(params, '$.store');
SET @state = JSON_VALUE(params, '$.state');
SET @partnerid = JSON_VALUE(params, '$.partner');
SELECT JSON_EXTRACT(params, '$.goods') INTO @tgoods;



SET @result_code = 1;
SET @result_message = '';
SET @i_csg = 0;
label1: while (@i_csg < JSON_LENGTH(@tgoods)) DO 
SELECT JSON_EXTRACT(@tgoods, CONCAT('$[', @i_csg, ']')) INTO @gg;
-- draft
if (JSON_VALUE(@gg, '$.f_id') IS NULL) then
	SET @draftid = UUID();
ELSE 
	SET @draftid = JSON_VALUE(@gg, '$.f_id');
END if;
INSERT INTO a_store_draft (f_id, f_document, f_store, f_type, f_goods, 
	f_qty, f_price, f_reason, f_base, f_row, f_comment)
	VALUES (@draftid, JSON_VALUE(@header, '$.f_id'),   @store, @ftype, JSON_VALUE(@gg, '$.f_goods'), 
	JSON_VALUE(@gg, '$.f_qty'), JSON_VALUE(@gg, '$.f_price'), JSON_VALUE(@header, '$.f_reason'), @draftid, JSON_VALUE(@gg, '$.f_row'), JSON_VALUE(@gg, '$.f_comment'));
	
	SET storerec = JSON_VALUE(@gg, '$.f_storerec');
	if (storerec IS NOT NULL) then
	UPDATE o_goods SET f_storerec=@draftid WHERE f_id=storerec;
	END if;
	
if (@state = 1 AND @ftype = 1) then	
	INSERT INTO a_store (f_id, f_document, f_store, f_type, f_goods, 
		f_qty, f_price, f_reason, f_base, f_basedoc, f_draft)
		VALUES (@draftid, JSON_VALUE(@header, '$.f_id'), @store, @ftype, JSON_VALUE(@gg, '$.f_goods'), 
		JSON_VALUE(@gg, '$.f_qty'), JSON_VALUE(@gg, '$.f_price'), JSON_VALUE(@header, '$.f_reason'), @draftid, JSON_VALUE(@header, '$.f_id'), @draftid);
		
	UPDATE c_goods SET f_lastinputprice=JSON_VALUE(@gg, '$.f_price') , f_supplier=@partnerid WHERE f_id=JSON_VALUE(@gg, '$.f_goods');
END if;

if (@state=1 AND @ftype=-1) then
	SELECT JSON_OBJECT('goods', JSON_DETAILED(@gg), 'date', JSON_VALUE(params, '$.date'), 
		'store', @store, 'draftid', @draftid, 'f_document', JSON_VALUE(@header, '$.f_id'), 'move', JSON_VALUE(params, '$.move'), 'storein', JSON_VALUE(params, '$.storein')) INTO @o;
	call sf_create_store_out(@o);
	SELECT @create_store_out INTO @result;
	if (JSON_VALUE(@result, '$.status') = 0) then
		if (@result_code = 1) then
			SET @result_message = 'Բացասական քանակ\n';
		END if;
		SET @result_code=0;
		SELECT CONCAT_WS('\n', @result_message, JSON_VALUE(@result, '$.message')) INTO @result_message;
		#select JSON_OBJECT('status', 0, 'message', JSON_VALUE(@result, '$.message')) INTO @create_store_goods;
		#leave sf_create_store_goods;
	END if;
END if;
	
SET @i_csg = @i_csg + 1;
END while label1;

select JSON_OBJECT('status', @result_code, 'message', @result_message) INTO @create_store_goods;

END$$

delimiter ;
DELIMITER ;

-- ========== store_open_document.sql ==========
delimiter $$
DROP FUNCTION if EXISTS sf_open_store_document$$
CREATE FUNCTION sf_open_store_document(params JSON)
RETURNS JSON 
BEGIN
-- 2025-10-12 13:45:28
	DECLARE docid CHAR(36) CHARACTER SET LATIN1 COLLATE LATIN1_GENERAL_CI DEFAULT JSON_VALUE(params, '$.f_id');
	DECLARE doc_header JSON;
	DECLARE doc_body JSON;
	DECLARE doc_client JSON;
	DECLARE doc_header_store JSON;
	DECLARE doc_add JSON;
	SELECT JSON_OBJECT('f_date', f_date, 'f_partner', f_partner,  'f_userid', f_userid, 'f_type', f_type, 'f_state', f_state, 'f_payment', f_payment,
		'f_amount', f_amount, 'f_comment', f_comment, 'f_paid', f_paid, 'f_body', f_body, 'f_currency', f_currency) INTO doc_header
		FROM a_header
		WHERE f_id=docid;
	if (doc_header IS NULL) then
		RETURN JSON_OBJECT('status', 0, 'data', 'Փասթաթուղթը գոյություն չունի');
	END if;
	
	select json_arrayagg(json_object(
		'f_id', d.f_id, 
		'f_goods', d.f_goods, 
		'f_goodsname', concat(g.f_name, if(g.f_scancode is null, '', concat(' ', g.f_scancode))), 
		'f_adgt', if (length(coalesce(g.f_adg, '')) > 0, g.f_adg, gr.f_adgcode) ,
		'f_qty', d.f_qty,
		'f_unitname', u.f_name, 
		'f_price', d.f_price, 
		'f_total', d.f_total, 
		'f_reason', d.f_reason, 
		'f_type', d.f_type, 
		'f_base', d.f_base, 
		'f_comment', d.f_comment, 
		'f_validdate', v.f_date)) INTO doc_body
		from a_store_draft d 
		left join c_goods g on g.f_id=d.f_goods
		left join c_units u on u.f_id=g.f_unit
		left join a_store_valid v on v.f_id=d.f_id 
		left join c_groups gr on gr.f_id=g.f_group
		where d.f_document=docid 
		order by d.f_row;
		
	SELECT JSON_OBJECT(
		'f_storein', f_storein, 
		'f_storeout', f_storeout)
		INTO doc_header_store
		FROM a_header_store WHERE f_id=docid;
		
	select JSON_OBJECT(
		'f_id', f_id, 
		'f_date', f_date, 
		'f_costumer', f_costumer,
		'f_order', f_order,
		'f_cash', f_cash,
		'f_amount', f_amount,
		'f_storedoc', f_storedoc, 
		'f_currency', f_currency,
		'f_flag', f_flag,
		'f_source', f_source) INTO doc_client		
		from b_clients_debts where f_storedoc=docid;
	
	RETURN JSON_OBJECT('status', 1, 'data', 
		JSON_OBJECT(
			'doc_header', JSON_DETAILED(doc_header), 
			'doc_header_store', JSON_DETAILED(doc_header_store),
			'doc_body', JSON_DETAILED(doc_body),
			'doc_client', JSON_DETAILED(doc_client)));
	
END$$
delimiter ;
DELIMITER ;

-- ========== store_out.sql ==========
delimiter $$
DROP FUNCTION if EXISTS sf_create_store_out$$
DROP PROCEDURE if EXISTS sf_create_store_out$$
CREATE procedure sf_create_store_out(params JSON)
BEGIN
DECLARE adraftid CHAR(36) CHARACTER SET latin1 COLLATE latin1_general_ci;
DECLARE goods_id INT;
DECLARE goods_store_id INT;
DECLARE store_id INT;
DECLARE qty DECIMAL(14,4);

#26/04/2025 14:27
SET adraftid = JSON_VALUE(params, '$.draftid');
SELECT JSON_EXTRACT(params, '$.goods') INTO @g; 
SELECT JSON_VALUE(@g, '$.f_goods') INTO goods_id;
SELECT JSON_VALUE(params, '$.store') INTO store_id;
SET qty = JSON_VALUE(@g, '$.f_qty');
SET @baseqty=qty;
SELECT f_storeid INTO goods_store_id FROM c_goods WHERE f_id=goods_id;
select coalesce(json_arrayagg(JSON_OBJECT('f_id', s.f_id, 'f_goods', s.f_goods, 'f_qty', sm.f_qty, 
	'f_price', sm.f_price, 'f_total', sm.f_total, 'f_document', s.f_document, 'f_base', s.f_base, 
	'f_basedoc', s.f_basedoc, 'f_date', d.f_date )), JSON_ARRAY()) INTO @sa
   from a_store s 
	left join ( 
	  select sum(ss.f_qty*ss.f_type) as f_qty, ss.f_price,  sum(ss.f_total*ss.f_type) as f_total, ss.f_base 
	  from a_store ss 
	  WHERE ss.f_store=store_id AND ss.f_goods=goods_store_id
	  group by ss.f_base  
	  having sum(ss.f_qty*ss.f_type)>0 
	  ) sm on sm.f_base=s.f_id
	inner join a_header d on d.f_id=s.f_document 
		where s.f_goods=goods_store_id and s.f_store=store_id and s.f_type=1 and sm.f_qty>0 
		order by d.f_date;
		
SET @i = 0;
SET @amount = 0;
label1: while (@i < JSON_LENGTH(@sa)) DO
	SELECT JSON_EXTRACT(@sa, CONCAT('$[', @i, ']')) INTO @s; 
	if (cast(JSON_VALUE(@s, '$.f_qty') AS DOUBLE) > qty) then
		INSERT INTO a_store (f_id, f_document, f_type, f_store, f_goods, f_qty, f_price, f_base, f_basedoc, f_draft, f_reason) 
			VALUES (UUID(), JSON_VALUE(params, '$.f_document'), -1, store_id, 
			goods_store_id, qty, JSON_VALUE(@s, '$.f_price'), 
			JSON_VALUE(@s, '$.f_base'), JSON_VALUE(@s, '$.f_basedoc'), JSON_VALUE(params, '$.draftid'), JSON_VALUE(@header, '$.f_reason'));
		SET @amount = @amount + (qty * JSON_VALUE(@s, '$.f_price'));
		SET qty = 0;
	ELSE 
		INSERT INTO a_store (f_id, f_document, f_type, f_store, f_goods, f_qty, f_price, f_base, f_basedoc, f_draft, f_reason) 
			VALUES (UUID(), json_value(params, '$.f_document'), -1, store_id, 
			goods_store_id, JSON_VALUE(@s, '$.f_qty'), JSON_VALUE(@s, '$.f_price'), 
			JSON_VALUE(@s, '$.f_base'), JSON_VALUE(@s, '$.f_basedoc'), JSON_VALUE(params, '$.draftid'), JSON_VALUE(@header, '$.f_reason'));
		SET @amount = @amount + (JSON_VALUE(@s, '$.f_qty') * JSON_VALUE(@s, '$.f_price'));		
		SET qty = qty - JSON_VALUE(@s, '$.f_qty');	
	END if;
	if (qty<0.001) then
		leave label1;
	END if;
	SET @i = @i + 1;
END while label1;	

UPDATE a_store_draft SET f_price=@amount/@baseqty WHERE f_id=adraftid;

if (JSON_VALUE(params, '$.move')=1) then
	SET @newdraft = UUID();
	INSERT INTO a_store_draft (f_id, f_document, f_store, f_type, f_goods, 
		f_qty, f_price, f_reason, f_base, f_row, f_comment)
		VALUES (@newdraft, JSON_VALUE(params, '$.f_document'), JSON_VALUE(params, '$.storein'), 1, JSON_VALUE(@g, '$.f_goods'), 
		JSON_VALUE(@g, '$.f_qty'), @amount/@baseqty, JSON_VALUE(@header, '$.f_reason'), @newdraft, JSON_VALUE(@g, '$.f_row'), JSON_VALUE(@g, '$.f_comment'));
	
	INSERT INTO a_store (f_id, f_document, f_store, f_type, f_goods, 
		f_qty, f_price, f_reason, f_base, f_basedoc, f_draft)
		VALUES (@newdraft, JSON_VALUE(params, '$.f_document'), JSON_VALUE(params, '$.storein'), 1, goods_store_id, 
		JSON_VALUE(@g, '$.f_qty'), @amount/@baseqty, JSON_VALUE(@header, '$.f_reason'), @newdraft, JSON_VALUE(params, '$.f_document'), @newdraft);
END if;
	

if (qty > 0) then
	SELECT f_name, f_scancode INTO @goods_name, @goods_scancode FROM c_goods WHERE f_id=goods_id;
	select JSON_OBJECT('status', 0, 'message', CONCAT_WS(' ', @goods_name, @goods_scancode,'-:', qty)) INTO @create_store_out;
ELSE 
	SELECT JSON_OBJECT('status', 1) INTO @create_store_out;
END if ;
		
END$$

delimiter ;
DELIMITER ;

-- ========== store_remove_doc.sql ==========
delimiter $$
DROP FUNCTION IF EXISTS sf_remove_store_doc $$
CREATE function sf_remove_store_doc (params JSON) RETURNS json BEGIN 
-- 2025-10-12 13:38:20
DECLARE removeid CHAR(36) CHARACTER SET LATIN1 COLLATE LATIN1_GENERAL_CI; 
DECLARE cashdoc CHAR(36) CHARACTER SET LATIN1 COLLATE LATIN1_GENERAL_CI;
SET removeid = JSON_VALUE(params, '$.removeid'); 

#check related doc if this is a input
SELECT  json_arrayagg( JSON_OBJECT( 'doc',s.f_document,'date',d.f_date,'user',d.f_userid ) ) INTO @relateddocs
FROM a_store s
INNER JOIN a_header d
ON d.f_id = s.f_document
WHERE f_basedoc = removeid
AND f_document <> removeid
AND s.f_type = -1; 

IF(@relateddocs IS NOT NULL) THEN 
       RETURN JSON_OBJECT( 'status', 0, 'reason', JSON_DETAILED(@relateddocs) ); 
END if; 

#select cash doc
SELECT  f_baseonsale
       ,f_cashuuid INTO @baseonsale
       ,cashdoc
FROM a_header_store
WHERE f_id = removeid; 
DELETE FROM a_store WHERE f_document = removeid; 
delete FROM a_store_draft WHERE f_document = removeid; 
delete FROM b_clients_debts WHERE f_storedoc = removeid; 
delete FROM a_header WHERE f_id = removeid; 
delete FROM a_header_store WHERE f_id = removeid; 
IF(cashdoc IS NOT null) THEN 
       delete FROM e_cash WHERE f_header = cashdoc; 
       delete FROM a_header_cash WHERE f_id = cashdoc; 
       delete FROM a_header  WHERE f_id = cashdoc; 
END if; 
delete FROM a_store_dish_waste WHERE f_document = removeid; 
RETURN JSON_OBJECT('status', 1); END $$
delimiter ;
DELIMITER ;
